insert into public.events (id,slug,title_ja,title_zh,category,summary,fees,conditions,status,verified_at,updated_at,image) values ('ave-virtus-store-2026','ave-virtus-store-2026','Ave Mujica 7th LIVE「Virtus」開催記念 BanG Dream! STORE 連動キャンペーン','Ave Mujica「Virtus」池袋 STORE 联动与周边先行销售','其他联动','10月20日起先行销售部分Live周边。购买收据有效期为10月20日～11月1日，纪念贴纸兑换期为10月24日～11月1日；图内会场展位名称曾更正，请以公告文字为准。',null,'["商品、赠品与名额可能用尽，请查官方最新公告。","本条仅收录池袋实体店；演唱会会场展位不视作全期间营业门店。","购买限制为每次结账各种最多3件；可能临时变更。"]','published','2026-10-28T09:00:00+09:00','2026-10-28T09:00:00+09:00','{"url":"https://bushiroad-creative.com/wordpress/wp-content/uploads/2026/09/19125206/BDP_AM_virtus_store_POP_B2-1024x1447.jpg","alt":"Ave Mujica 7th LIVE「Virtus」開催記念 BanG Dream! STORE 連動キャンペーン · 官方活动图","source_url":"https://bushiroad-creative.com/topics/106228/","checked_on":"2026-10-28"}') on conflict do nothing;
