insert into public.events (id,slug,title_ja,title_zh,category,summary,fees,conditions,status,verified_at,updated_at,image,translated_rules,gallery) values ('mygo-9th-kobe-2026','mygo-9th-kobe-2026','MyGO!!!!! 9th LIVE「つなぎ目の向こうに」- 神戸再景編 -','MyGO!!!!! 第9次 Live「つなぎ目の向こうに」神户再景篇','音乐和声优活动','MyGO!!!!! 神户再景篇：一般先着及已结束的专辑附券先行。2026-11-14、2026-11-15，神户 ワールド記念ホール（神戸ポートアイランドホール）。票务与附券资格见下方；所有已列报名时间为日本时间。','一般指定席8,800日元；附周边一般指定席13,200日元，A席17,600日元，S席25,300日元（含税）。','["商品、赠品与名额可能用尽，请查官方最新公告。","需要正式公演门票，购买CD并不直接获得本场门票。"]','published','2026-10-29T13:33:33.947Z','2026-10-29T13:33:33.947Z','{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/09/10185610/68a97586-82af2e92-fdb9a250-4094ccb4.jpg","alt":"MyGO!!!!! 9th LIVE「つなぎ目の向こうに」- 神戸再景編 - · 官方活动图","source_url":"https://bang-dream.com/events/mygo_9th_hyogo/","checked_on":"2026-10-28"}','[{"title":"商品附券抽选（已截止）","text_zh":"初回生产分附申込券；每个序列号可申请DAY1及DAY2，每次最多4张。该轮已经结束，当前一般先着不使用这张附券。 受理：2026-07-19T21:00 至 2026-08-24T23:59（日本时间）。","evidence_ja":"最速先行抽選（受付終了）\n受付期間：2026年7月19日(日) 21:00 ～ 8月24日(月) 23:59まで\n※ MyGO!!!!! 3rd Album「致並跡」 初回生産分に封入の申込券でご応募いただけます。\n※封入のシリアル1枚で、DAY1・DAY2の両公演ともにご応募いただけます。\n1回につき4枚までお申込みいただけます。","id":"mygo-9th-kobe-2026-rule-0","kind":"参加","source_url":"https://bang-dream.com/events/mygo_9th_hyogo/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"当前一般先着售票","text_zh":"10月17日12:00起一般先着，达到上限即止，每人最多4张；S席已在先行达到上限，不在本轮销售。未另列截止时刻。","evidence_ja":"一般発売\n受付期間：2026年10月17日(土) 12:00 ～\n受付はこちら\n※先着順・上限数に達し次第終了\n※お一人様につき4枚までお申込みいただけます。\n※S席(特製グッズ付き)は先行受付分にて上限数に達したため受付はございません。","id":"mygo-9th-kobe-2026-rule-1","kind":"参加","source_url":"https://bang-dream.com/events/mygo_9th_hyogo/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"票种与价格","text_zh":"含特典S席25,300、A席17,600、一般指定席13,200日元；不含特典一般指定席8,800日元，均含税。","evidence_ja":"料金\nS席(特製グッズ付き)：25,300円(税込)\nA席(特製グッズ付き)：17,600円(税込)\n一般指定席(特製グッズ付き)：13,200円(税込)\n一般指定席：8,800円(税込)","id":"mygo-9th-kobe-2026-rule-2","kind":"参加","source_url":"https://bang-dream.com/events/mygo_9th_hyogo/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"票券特典领取","text_zh":"附特典票赠特制斜挎包；S席不在当前一般发售范围。","evidence_ja":"グッズ付きチケット特典\n・特製ボディバッグ\n販売情報\n一般発売\n受付期間：2026年10月17日(土) 12:00 ～\n受付はこちら\n※先着順・上限数に達し次第終了\n※お一人様につき4枚までお申込みいただけます。\n※S席(特製グッズ付き)は先行受付分にて上限数に達したため受付はございません。\nプレイガイド先行（受付終了）\n受付期間：2026年9月13日(日) 12:00 ～ 10月4日(日) 23:59まで\n※お一人様につき4枚までお申込みいただけます。\n※S席(特製グッズ付き)は、最速先行抽選の入金キャンセル分のみの受付となります。\n最速先行抽選（受付終了）\n受付期間：2026年7月19日(日) 21:00 ～ 8月24日(月) 23:59まで\n※ MyGO!!!!! 3rd Album「致並跡」 初回生産分に封入の申込券でご応募いただけます。\n※封入のシリアル1枚で、DAY1・DAY2の両公演ともにご応募いただけます。\n1回につき4枚までお申込みいただけます。","id":"mygo-9th-kobe-2026-rule-3","kind":"参加","source_url":"https://bang-dream.com/events/mygo_9th_hyogo/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"实名证件与转让限制","text_zh":"禁止转卖和转让；可能实施本人核验，须携带规定的身份证件。eplus电子票向同行者的合法分配可以使用。","evidence_ja":"2. チケットの転売・譲渡について\nチケットの転売・譲渡は、いかなる場合も固く禁止しております。\n転売対策のため、入場前に全てのお客様についてご本人様確認を実施させていただく場合がございますので、公的な顔写真付身分証明書1点（免許証・パスポート・在留カード・障害者手帳・顔写真付クレジットカード・顔写真付住民基本台帳カード・マイナンバーカードなど）または顔写真付学生証（生徒手帳・学生手帳）1点を必ずご準備ください。\n顔写真付でない学生証（生徒手帳・学生手帳）をお持ちの方は、顔写真付でない学生証（生徒手帳・学生手帳）1点に加え、ご本人名義の保険証または保険証の写し1点の合計2点をご用意の上、ご来場ください。\n身分証をご提示いただけない場合、入場をお断りする場合がございます。\n※イープラス「スマチケ」など、電子チケットの分配機能を用いた同行者への分配は問題ございません。","id":"mygo-9th-kobe-2026-rule-4","kind":"参加","source_url":"https://bang-dream.com/events/mygo_9th_hyogo/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"年龄、入场与退款","text_zh":"学龄前儿童不能入场，一票一人且仅对应场次有效。除公演取消或延期外不退款；附特典票的赠品在会场领取，不补寄，遗漏须当日申告。","evidence_ja":"・未就学児の入場はできません。\n・チケットは券面に記載の公演日、会場でのみ有効となります。\n・1枚のチケットを複数のお客様で使用することはできません（チケット1枚につきお客様1名様のみのご入場となります）。\n・公演中止、延期の場合以外でのチケットの払い戻しはいかなる理由でも行いません。予めご了承ください。\n・グッズ付きチケットをご購入された場合、グッズは原則として会場でのお渡しとなります。いかなる理由でも事前または事後の発送は受け付けておりませんので予めご了承ください。グッズのお受け取り忘れにつきましても、開催当日のご申告のみ対応させていただきます。後日のご連絡にはお応えいたしかねますので、グッズはお忘れなくお受け取りください。その他入場時等の配布物につきましても同様とさせていただきます。","id":"mygo-9th-kobe-2026-rule-5","kind":"参加","source_url":"https://bang-dream.com/events/mygo_9th_hyogo/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"}]','[{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/09/10185610/68a97586-82af2e92-fdb9a250-4094ccb4.jpg","alt":"MyGO!!!!! 9th LIVE「つなぎ目の向こうに」- 神戸再景編 -","source_url":"https://bang-dream.com/events/mygo_9th_hyogo/","checked_on":"2026-10-30"},{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/07/30115049/1d6aa384-f4ad028f-1df08892-ae57e5cb-1024x924.jpg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://bang-dream.com/events/mygo_9th_hyogo/","checked_on":"2026-10-30"},{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/07/17184339/531acae0-fe98cb89-e13d5a8b-45ce704b-1024x577.jpg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://bang-dream.com/events/mygo_9th_hyogo/","checked_on":"2026-10-30"},{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/10/15100023/d8a1b723-825298fc-46145f3c-a9b78054-1024x576.jpg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://bang-dream.com/events/mygo_9th_hyogo/","checked_on":"2026-10-30"}]') on conflict do nothing;
