insert into public.events (id,slug,title_ja,title_zh,category,summary,fees,conditions,status,verified_at,updated_at,image,translated_rules,gallery) values ('millsage-ikka-special-2027','millsage-ikka-special-2027','millsage×一家Dumb Rock! SPECIAL LIVE','millsage × 一家Dumb Rock! 联合特别 Live','音乐和声优活动','2027年1月11日在东京 Kanadevia Hall 举办，预计17:00入场、18:00开演。票务平台先行受理至2026年11月16日23:59，每人最多2张；另需饮料费。站席和指定席的价格、周边配置不同。 eplus确认本轮为PG先行抽选，官方每人限2张。','站立区附周边16,500日元；看台指定席附周边12,100日元；看台指定席8,800日元，另收饮料费。','["商品、赠品与名额可能用尽，请查官方最新公告。","除门票附赠的特制手环灯外，禁止携带使用其他发光应援物。"]','published','2026-10-29T13:42:42.947Z','2026-10-29T13:42:42.947Z','{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/10/08200702/f64f8451-317189bd-5e3aaa44-7ac66bd5.jpg","alt":"millsage×一家Dumb Rock! SPECIAL LIVE · 官方活动图","source_url":"https://bang-dream.com/events/millsage_ikka-dumb-rock/","checked_on":"2026-10-28"}','[{"title":"先行受理","text_zh":"2026年10月9日19:00至11月16日23:59受理，每人最多2张；对应eplus票务页已明确标为抽选PG先行。","evidence_ja":"受付期間：2026年10月9日(金) 19:00～ 11月16日(月) 23:59\n※お一人様につき2枚までお申し込みいただけます。","id":"millsage-ikka-special-2027-rule-0","kind":"参加","source_url":"https://bang-dream.com/events/millsage_ikka-dumb-rock/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"应援灯","text_zh":"仅可携带、使用门票特典的特制手环灯，其他发光应援物禁止。","evidence_ja":"本公演ではチケット特典グッズ【特製バングルライト】を除く光り物の応援アイテム(サイリウム、ペンライト、バングルライト、リングライト、その他電飾やそれを伴うもの等)の持ち込み、使用を禁止とさせていただきます。","id":"millsage-ikka-special-2027-rule-1","kind":"参加","source_url":"https://bang-dream.com/events/millsage_ikka-dumb-rock/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"票价、特典与饮料费","text_zh":"含特典Arena站席16,500日元、含特典看台指定席12,100日元、普通看台指定席8,800日元，均含税，另收饮料费。特典为特制手环灯，设计尚待公布。","evidence_ja":"料金\nアリーナスタンディング (特製グッズ付き)：16,500円(税込)\nスタンド指定席(特製グッズ付き)：12,100円(税込)\nスタンド指定席：8,800円(税込)\n※別途ドリンク代が必要です。\nグッズ付きチケット特典\n特製バングルライト\n※デザインは後日公開いたします。","id":"millsage-ikka-special-2027-rule-2","kind":"参加","source_url":"https://bang-dream.com/events/millsage_ikka-dumb-rock/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"实名与同行票","text_zh":"可能核验本人身份，须携带规定的带照片证件；禁止转卖、转让，电子票向同行者的合法分配可以使用。","evidence_ja":"2. チケットの転売・譲渡について\nチケットの転売・譲渡は、いかなる場合も固く禁止しております。\n転売対策のため、入場前に全てのお客様についてご本人様確認を実施させていただく場合がございますので、公的な顔写真付身分証明書1点（免許証・パスポート・在留カード・障害者手帳・顔写真付クレジットカード・顔写真付住民基本台帳カード・マイナンバーカードなど）または顔写真付学生証（生徒手帳・学生手帳）1点を必ずご準備ください。\n顔写真付でない学生証（生徒手帳・学生手帳）をお持ちの方は、顔写真付でない学生証（生徒手帳・学生手帳）1点に加え、ご本人名義の保険証または保険証の写し1点の合計2点をご用意の上、ご来場ください。\n身分証をご提示いただけない場合、入場をお断りする場合がございます。\n※イープラス「スマチケ」など、電子チケットの分配機能を用いた同行者への分配は問題ございません。","id":"millsage-ikka-special-2027-rule-3","kind":"参加","source_url":"https://bang-dream.com/events/millsage_ikka-dumb-rock/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"},{"title":"年龄及取消退款","text_zh":"学龄前儿童不得入场，一票一人且仅限对应场次。除公演取消或延期外不退款；特典现场领取，不补寄。","evidence_ja":"・未就学児の入場はできません。\n・チケットは券面に記載の公演日、会場でのみ有効となります。\n・1枚のチケットを複数のお客様で使用することはできません（チケット1枚につきお客様1名様のみのご入場となります）。\n・公演中止、延期の場合以外でのチケットの払い戻しはいかなる理由でも行いません。予めご了承ください。\n・グッズ付きチケットをご購入された場合、グッズは原則として会場でのお渡しとなります。いかなる理由でも事前または事後の発送は受け付けておりませんので予めご了承ください。グッズのお受け取り忘れにつきましても、開催当日のご申告のみ対応させていただきます。後日のご連絡にはお応えいたしかねますので、グッズはお忘れなくお受け取りください。その他入場時等の配布物につきましても同様とさせていただきます。","id":"millsage-ikka-special-2027-rule-4","kind":"参加","source_url":"https://bang-dream.com/events/millsage_ikka-dumb-rock/","image_url":null,"image_sha256":null,"checked_on":"2026-10-29"}]','[{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/10/08200702/f64f8451-317189bd-5e3aaa44-7ac66bd5.jpg","alt":"millsage×一家Dumb Rock! SPECIAL LIVE","source_url":"https://bang-dream.com/events/millsage_ikka-dumb-rock/","checked_on":"2026-10-30"},{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/10/15192501/bb85e4ba-8e444ee0-5c5a846f-11c07c98-1024x576.jpg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://bang-dream.com/events/millsage_ikka-dumb-rock/","checked_on":"2026-10-30"}]') on conflict do nothing;
