insert into public.events (id,slug,title_ja,title_zh,category,summary,image,fees,conditions,status,verified_at,updated_at,benefits,gallery) values ('nijigasaki-kitchen-7th-2026','nijigasaki-kitchen-7th-2026','虹ヶ咲学園キッチンカー7周年記念ドリンク販売のお知らせ','虹咲学园餐车 7 周年纪念饮品','联动咖啡厅','周年饮品与通常饮品联动赠送餐车纸模型立牌。餐车当天营业位置和时间需查看运营方公告。','{"url":"https://www.lovelive-anime.jp/nijigasaki/module/image.php?img_path=/lovelive/jp/news/2026/10/09/1002/aWEwRvT6ljb082jN/Bm78OcTtARr2bwgC.jpeg","alt":"虹咲学园餐车 7 周年纪念饮品 · 官方公告图","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6690","checked_on":"2026-10-28"}',null,'["当前公告未列出完整街道地址；不要把常设咖啡厅地址当作餐车位置。","赠品剩余数量未公开；是否仍可领取请现场确认。"]','published','2026-10-28T12:00:00+09:00','2026-10-28T12:00:00+09:00','[{"id":"niji-kitchen-paper","title":"同次买 3 杯：餐车纸模型立牌","rule":"同次购买 3 杯，必须至少含 1 杯 7 周年纪念饮品。其余可为通常饮品；不能按单纯消费金额计算。","threshold_yen":null,"threshold_quantity":3,"channel":"门店","scope":"虹咲餐车：周年纪念饮品与通常饮品","venue_ids":[],"starts_on":"2026-10-30","ends_on":"2026-11-23","selection":"未说明","receipt_combination":"不可合并","while_supplies_last":null,"image":{"url":"https://www.lovelive-anime.jp/nijigasaki/module/image.php?img_path=/lovelive/jp/news/2026/10/09/1002/aWEwRvT6ljb082jN/Bm78OcTtARr2bwgC.jpeg","alt":"餐车 7 周年饮品与纸模型立牌公告","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6690","checked_on":"2026-10-28"},"source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6690","checked_on":"2026-10-28"}]','[]') on conflict do nothing;
