insert into public.events (id,slug,title_ja,title_zh,category,summary,image,fees,conditions,status,verified_at,updated_at,benefits,gallery,translated_rules) values ('lovelive-hep-navio-2026','lovelive-hep-navio-2026','「THEキャラCAFE HEPナビオ店×ラブライブ！シリーズ」開催決定！','LoveLive! 系列 × THEキャラCAFE HEP NAVIO','联动咖啡厅','2026年11月5日至29日在大阪HEP NAVIO 7层THEキャラCAFÉ举行系列联动，提供餐饮与新商品。11月5日至8日须事前先着预约，10月27日20:00起开放，每个预约日前一天23:59截止；其他日期可能整理券限流。生日菜单：11月5日至17日为星空凛、天王寺璃奈；11月17日至29日为叶月恋，17日同时属于原文列出的两段。图片中的菜单价格、特典和商品细则须另行读图复核。','{"url":"https://www.lovelive-anime.jp/nijigasaki/module/image.php?img_path=/lovelive/jp/news/2026/10/09/1002/GK3AgAlpsasz7DKM/fmNiUKzayY4InVz5.jpeg","alt":"LoveLive! 系列 × THEキャラCAFE HEP NAVIO · 官方公告图","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6692","checked_on":"2026-10-28"}',null,'["这是系列共同联动；不能将未公布菜单都标作虹咲专属。","采用官网更正后的 10/27 20:00 开放时间，旧版 10/19 时间无效。","本公告未公布满赠门槛，不推定有消费特典。"]','published','2026-10-28T12:00:00+09:00','2026-10-30T14:10:44.737Z','[]','[{"url":"https://www.lovelive-anime.jp/hasunosora/shared/api/image.php?img_path=/lovelive/jp/news/2026/10/29/1002/Ysgk8irbHc36KBQM/LKSFea5ZEz0O0sBx.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6743","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/hasunosora/shared/api/image.php?img_path=/lovelive/jp/news/2026/10/29/1002/PUzJcAwCKcBkRBMG/OImGraVIpOhfXE5U.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6743","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/hasunosora/shared/api/image.php?img_path=/lovelive/jp/news/2026/10/29/1002/ESTV6iH0SG3H0JLP/ESZpDUFuAh8JgmmI.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6743","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/hasunosora/shared/api/image.php?img_path=/lovelive/jp/news/2026/10/29/1002/iU8MQwzlC1EX3a6L/EuitoNIs09RGunJ1.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6743","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/hasunosora/shared/api/image.php?img_path=/lovelive/jp/news/2026/10/29/1002/0C4Q0EvyzRTaE8Se/zYRbvYiayRd5n09o.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6743","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/hasunosora/shared/api/image.php?img_path=/lovelive/jp/news/2026/10/29/1002/YklRgRIjivHk6Jgm/xfl1Zn3LLMPVxwYJ.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6743","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/hasunosora/shared/api/image.php?img_path=/lovelive/jp/news/2026/10/29/1002/7dCfkT1AcfURoNcD/AGVnQPJRpNWvphXP.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6743","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/nijigasaki/module/image.php?img_path=/lovelive/jp/news/2026/10/09/1002/GK3AgAlpsasz7DKM/fmNiUKzayY4InVz5.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6692","checked_on":"2026-10-30"}]','[{"title":"首四天事前先着预约","text_zh":"11月5日至8日必须事前先着预约；10月27日20:00（日本时间）起受理，每个到店日前一天23:59截止。其余日期也可能因拥挤发整理券并限制入店。","evidence_ja":"混雑が予想されるため、2026年11月5日(木)～11月8日(日)の4日間は事前先着予約制とさせていただきます。","id":"lovelive-hep-navio-2026-rule-0","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6743","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"预约期限与限流","text_zh":"仅11月5日至8日适用事前先着预约，各到店日前一天23:59截止（日本时间）；11月9日以后未公告同一预约规则，拥挤时仍可能整理券限流。详见官方公告及 https://www.the-chara.com/blog/?p=123684 。","evidence_ja":"■事前先着予約スケジュール\n申し込み期間 ：2026年10月27日(火)20:00～各予約日の前日の23:59まで\n事前予約対象日：2026年11月5日(木)～11月8日(日)の4日間\n※混雑状況により、上記日程以外も整理券対応にて入店制限させていただく場合がございます。\n予めご了承くださいませ。","id":"lovelive-hep-navio-2026-rule-1","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6743","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"生日菜单期间","text_zh":"星空凛、天王寺璃奈：11月5日至17日；叶月恋：11月17日至29日。17日在官方两段中重叠，保留原文，不自行改为18日。","evidence_ja":"★11/5(木)～11/17(火) 星空 凜・天王寺璃奈\n★11/17(火)～11/29(日) 葉月 恋","id":"lovelive-hep-navio-2026-rule-2","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6743","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"}]') on conflict do nothing;
