insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-ca26a0cb7e16bb32','official-ca26a0cb7e16bb32','Morfonica LIVE「eleganza」','Morfonica 演唱会「eleganza」','音乐和声优活动','2027年1月9日在东京 Kanadevia Hall 举办，预计17:00入场、18:00开演。新增票务平台第二轮先行受理：2026年10月29日18:00至11月29日23:59（日本时间；北京时间分别为17:00、22:59）。上一轮先行已结束；eplus已确认本轮为抽选；本轮限购以申请页实际说明为准，不沿用上一轮4张限制。','{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/09/15164842/a61da4d6-7f149f0f-4eb00663-f4409050.png","alt":"Morfonica 演唱会「eleganza」","source_url":"https://bang-dream.com/events/eleganza/","checked_on":"2026-10-30"}','[{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/09/15164842/a61da4d6-7f149f0f-4eb00663-f4409050.png","alt":"Morfonica LIVE「eleganza」","source_url":"https://bang-dream.com/events/eleganza/","checked_on":"2026-10-30"},{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/09/18121237/6ef94b14-56a114b4-1af78889-6e246664.jpg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://bang-dream.com/events/eleganza/","checked_on":"2026-10-30"}]','[]','[{"title":"新增第二轮先行","text_zh":"第二轮先行：2026年10月29日18:00至11月29日23:59，日本时间。对应eplus页面已确认抽选受理；本轮限购未在主公告独立写明，不沿用上一轮限制。","evidence_ja":"プレイガイド二次先行\n受付期間：2026年10月29日(木) 18:00 ～ 11月29日(日) 23:59","id":"auto-ca26a0cb7e16bb32-rule-0","kind":"参加","source_url":"https://bang-dream.com/events/eleganza/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"上一轮已结束","text_zh":"2026年9月22日21:00至10月18日23:59的先行已结束。每次最多4张的说明位于这一段之后，不能据此确定第二轮限购。","evidence_ja":"プレイガイド先行 ※受付終了\n受付期間：2026年9月22日(火・祝) 21:00 ～ 10月18日(日) 23:59\n※1回につき4枚までお申し込みいただけます。","id":"auto-ca26a0cb7e16bb32-rule-1","kind":"参加","source_url":"https://bang-dream.com/events/eleganza/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"票价与饮料费","text_zh":"含特制周边的Arena站席S区22,000日元、A区16,500日元，含周边看台指定席14,300日元，普通看台指定席9,900日元，均含税，另收饮料费。","evidence_ja":"アリーナスタンディング Sエリア(特製グッズ付き)：22,000円(税込)\nアリーナスタンディング Aエリア(特製グッズ付き)：16,500円(税込)\nスタンド指定席(特製グッズ付き)：14,300円(税込))\nスタンド指定席：9,900円(税込)\n※別途ドリンク代が必要です。","id":"auto-ca26a0cb7e16bb32-rule-2","kind":"参加","source_url":"https://bang-dream.com/events/eleganza/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"站席分区","text_zh":"站席必须在电子票记载的分区观看，不能跨区。","evidence_ja":"・電子チケットに記載のブロックにてご観覧いただきます。記載以外のブロックでのご観覧はできませんのであらかじめご了承ください。","id":"auto-ca26a0cb7e16bb32-rule-3","kind":"参加","source_url":"https://bang-dream.com/events/eleganza/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"儿童限制","text_zh":"学龄前儿童不得入场。","evidence_ja":"・未就学児の入場はできません。","id":"auto-ca26a0cb7e16bb32-rule-4","kind":"参加","source_url":"https://bang-dream.com/events/eleganza/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","官方售票页明确为抽选；日本时间。核对票务原文：https://eplus.jp/morfonica-eleganza/"]','published','2026-10-30T14:10:44.737Z','2026-10-30T14:10:44.737Z') on conflict do nothing;
