insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-0d9f7fdb753dc318','official-0d9f7fdb753dc318','一家Dumb Rock! 1st GIG「ピース＆グルーヴ」','一家Dumb Rock! 首场GIG「ピース＆グルーヴ」','音乐和声优活动','2026年12月12日在东京duo MUSIC EXCHANGE举行，预计17:00入场、18:00开演。全站席6,600日元（含税）；最速先行使用首张单曲附券，受理截止为2026年11月1日23:59。','{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/06/12200218/831893d3-f2491352-7e8e8d09-e6759bb3.jpg","alt":"一家Dumb Rock! 首场GIG「ピース＆グルーヴ」","source_url":"https://bang-dream.com/events/ikka-dumb-rock_1st/","checked_on":"2026-10-30"}','[{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/06/12200218/831893d3-f2491352-7e8e8d09-e6759bb3.jpg","alt":"一家Dumb Rock! 1st GIG「ピース＆グルーヴ」","source_url":"https://bang-dream.com/events/ikka-dumb-rock_1st/","checked_on":"2026-10-30"}]','[]','[{"title":"附券与数量","text_zh":"使用首张单曲「ピースフル・ピーシーズ！」首批生产版附券，每人最多申请2张。","evidence_ja":"※ 一家Dumb Rock! 1st Single「ピースフル・ピーシーズ！」 初回生産分に封入の申込券でご応募いただけます。\n※お一人様につき2枚までお申込みいただけます。","id":"auto-0d9f7fdb753dc318-rule-0","kind":"参加","source_url":"https://bang-dream.com/events/ikka-dumb-rock_1st/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"应援物","text_zh":"禁止携带和使用任何发光应援物，站席请遵守整理编号和现场指引。","evidence_ja":"本公演では光り物の応援アイテム(サイリウム、ペンライト、バングルライト、リングライト、その他電飾やそれを伴うもの等)の持ち込み、使用を禁止とさせていただきます。","id":"auto-0d9f7fdb753dc318-rule-1","kind":"参加","source_url":"https://bang-dream.com/events/ikka-dumb-rock_1st/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","需首张单曲「ピースフル・ピーシーズ！」首批附券，每人最多2张。"]','published','2026-10-30T14:10:44.737Z','2026-10-30T14:10:44.737Z') on conflict do nothing;
