insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-a48a7b8fd72221ef','official-a48a7b8fd72221ef','LoveLive! Orchestra Concert＜2027年公演＞','μ''s 嘉宾演唱：LoveLive! Orchestra Concert 2027','音乐和声优活动','2027年1月10–11日在千叶县文化会馆举办，由管弦乐团演奏、μ''s五位成员嘉宾演唱。1月10日17:30开演，11日12:00及16:30两场。一般第一次抽选至11月23日23:59（日本时间），每人每场最多4张。','{"url":"https://www.lovelive-anime.jp/otonokizaka/event/lovelive_orchestra2027/image.php?img_path=/lovelive/jp/live/2026/09/24/1002/IBCb2VrhHf38f0QG/82CxKr6QnTcTlRGE.jpeg","alt":"μ''s 嘉宾演唱：LoveLive! Orchestra Concert 2027","source_url":"https://www.lovelive-anime.jp/otonokizaka/event/lovelive_orchestra2027/","checked_on":"2026-10-30"}','[{"url":"https://www.lovelive-anime.jp/otonokizaka/event/lovelive_orchestra2027/image.php?img_path=/lovelive/jp/live/2026/09/24/1002/IBCb2VrhHf38f0QG/82CxKr6QnTcTlRGE.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/otonokizaka/event/lovelive_orchestra2027/","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/otonokizaka/event/lovelive_orchestra2027/image.php?img_path=/lovelive/jp/live/2026/10/07/1003/47zMQN5JfoSY3NMj/MYi4vBZkGRZEkJfT.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/otonokizaka/event/lovelive_orchestra2027/","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/otonokizaka/event/lovelive_orchestra2027/image.php?img_path=/lovelive/jp/live/2026/10/07/1003/P4eKOanHU44ZADtj/D8novKuwZINWcCt3.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/otonokizaka/event/lovelive_orchestra2027/","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/otonokizaka/event/lovelive_orchestra2027/image.php?img_path=/lovelive/jp/live/2026/10/07/1003/MNN310yVqQX5HFM9/CJpKNNmUqNrypW5e.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/otonokizaka/event/lovelive_orchestra2027/","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/otonokizaka/event/lovelive_orchestra2027/image.php?img_path=/lovelive/jp/live/2026/10/07/1003/U5EoPXdQV4IFZ6Wd/q78jBwjdlssijrFb.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/otonokizaka/event/lovelive_orchestra2027/","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/otonokizaka/event/lovelive_orchestra2027/image.php?img_path=/lovelive/jp/live/2026/10/07/1003/lchC3FOFqM9A0pmu/SxpVNS0dCa3s4dfQ.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/otonokizaka/event/lovelive_orchestra2027/","checked_on":"2026-10-30"}]','[]','[{"title":"三场演出","text_zh":"1月10日16:30入场17:30开演；11日昼场11:00入场12:00开演，夜场15:30入场16:30开演。","evidence_ja":"【日程】\nDay.1 2027年1月10日（日） 16:30開場／17:30開演\nDay.2 2027年1月11日（月・祝） ＜昼公演＞11:00開場／12:00開演 ＜夜公演＞15:30開場／16:30開演\n【会場】\n千葉県文化会館","id":"auto-a48a7b8fd72221ef-rule-0","kind":"参加","source_url":"https://www.lovelive-anime.jp/otonokizaka/event/lovelive_orchestra2027/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"门票","text_zh":"指定席11,000日元（含税）；配信另行公布，不把配信票当现场票。","evidence_ja":"【チケット料金】\n全席指定：11,000円（税込）\n※＜有料生配信＞の同時実施を予定しております。詳細は後日ご案内いたします。\n※天候・災害等の諸事情により、開演時間・公演内容の変更、延期、または中止させていただく場合がございます。","id":"auto-a48a7b8fd72221ef-rule-1","kind":"参加","source_url":"https://www.lovelive-anime.jp/otonokizaka/event/lovelive_orchestra2027/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"一般第一次抽选","text_zh":"10月24日12:00至11月23日23:59（日本时间），11月28日13:00起公布结果；付款至12月1日21:00，每人每场最多4张，可申请多场。","evidence_ja":"一般発売（1次抽選）\n■受付URL： https://eplus.jp/lovelive_orchestra2027/\n■受付期間：2026年10月24日（土）12:00～11月23日（月・祝）23:59\n■当落発表：2026年11月28日（土）13:00～\n■入金期間：2026年11月28日（土）13:00～12月1日（火）21:00\n※枚数制限：お一人様、1公演につき4枚まで（複数公演申込可）","id":"auto-a48a7b8fd72221ef-rule-2","kind":"参加","source_url":"https://www.lovelive-anime.jp/otonokizaka/event/lovelive_orchestra2027/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"一般第二次抽选","text_zh":"11月28日12:00至12月20日23:59（日本时间），12月25日13:00起公布结果；每人每场最多4张，仅信用卡支付。","evidence_ja":"一般発売（2次抽選）\n■受付URL： https://eplus.jp/lovelive_orchestra2027/\n■受付期間：2026年11月28日（土）12:00～12月20日（日）23:59\n■当落発表：2026年12月25日（金）13:00～\n※枚数制限：お一人様、1公演につき4枚まで（複数公演申込可）\n※クレジットカード決済のみ受付となります。","id":"auto-a48a7b8fd72221ef-rule-3","kind":"参加","source_url":"https://www.lovelive-anime.jp/otonokizaka/event/lovelive_orchestra2027/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"年龄与实名","text_zh":"3岁以下禁止入场，3岁以上收费；需要eplus会员、申请者及同行者人脸照片登记，携带照片身份证件。中选后不能取消，另有手续费。","evidence_ja":"●注意事項●\n※3歳以上有料（3歳未満のお子様はご入場いただけません）\n※お申込み時にイープラスの会員登録（無料）が必要です。\n※必ず受付画面にて、注意事項をご確認の上、お申込みください。\n※抽選販売分は先着順での受付ではございませんので、受付期間内にお申込みください。当落および座席などは、期間内にお申込みいただいた中から抽選で決定いたします。\n※お席に関してのお問合せには、お答えできません。\n※お申込み内容の変更・取消しは受付期間中のみおこなえます。当選後の変更・取消し(購入辞退)は一切お受けできませんのでご注意ください。\n※チケット代金の他に各種手数料が必要となります。\n※アルコール類の持込、及び飲酒してのご入場は固くお断りいたします。\n※開場・開演時間、出演者は諸事情により変更になる場合がございます。それに伴うチケット代・交通費等の払い戻しはいたしません。あらかじめご了承ください。\n※ご来場のお客様におかれましては、公演における注意事項を必ずお読みいただき、遵守くださいますようお願いいたします。ご協力いただけない場合、ご入場いただけない可能性もございますので、あらかじめご了承ください。\n※顔認証入場システムを利用したチケット販売のため、顔写真登録が必要となります。必ず来場者ご本人様がお申込みください。（チケットを2枚以上購入される場合、同行者の顔写真登録も必要となります。）\n※顔認証入場システムでご本人と判断できない場合、顔写真付きの公的身分証でご本人確認をさせていただきますので、必ずご持参ください。\n▼顔認証入場システムのご利用について\nhttps://eplus.jp/faceticket_about/\n■同行者登録とは？\nhttps://eplus.jp/sf/guide/fellow-ep/\n■【同行者登録】手続きはこちら\nhttps://member.eplus.jp/update-dokosha\n※受付開始前からお手続きいただけます。","id":"auto-a48a7b8fd72221ef-rule-4","kind":"参加","source_url":"https://www.lovelive-anime.jp/otonokizaka/event/lovelive_orchestra2027/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","一般第一次抽选，每人每场最多4张；官网未列附券商品要求。第二次为11月28日12:00至12月20日23:59，另见规则；1月11日昼夜两场。"]','published','2026-10-30T14:10:44.737Z','2026-10-30T14:10:44.737Z') on conflict do nothing;
