insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-70dd2d30c1a28bb3','official-70dd2d30c1a28bb3','ラブライブ！蓮ノ空女学院スクールアイドルクラブ Link Live Dream ～103期卒業公演～｜LIVE＆EVENT','莲之空 Link Live Dream「103期毕业公演」','音乐和声优活动','2027年1月23、24日在东京日本武道馆举办。Day1与Day2分别使用Extra单曲及电影BD特装限定版附券报名，开始日期不同，均于11月8日23:59（日本时间）截止。花宫初奈仅Day2出演。升席须先中选并付款，另行抽选。','{"url":"https://www.lovelive-anime.jp/hasunosora/live-event/image.php?img_path=/lovelive/jp/live/2026/10/14/1002/FyGJDIH74hlE7GXY/4d7rb3OPiFwtiDJ1.jpeg","alt":"莲之空 Link Live Dream「103期毕业公演」","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream103","checked_on":"2026-10-30"}','[{"url":"https://www.lovelive-anime.jp/hasunosora/live-event/image.php?img_path=/lovelive/jp/live/2026/10/14/1002/FyGJDIH74hlE7GXY/4d7rb3OPiFwtiDJ1.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream103","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/hasunosora/live-event/image.php?img_path=/lovelive/jp/live/2026/10/14/1002/h0qfqHv1AfvwcZ1Z/wm77KuI55wUJ5jld.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream103","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/hasunosora/live-event/image.php?img_path=/lovelive/jp/live/2026/10/14/1002/srtfSe7isCMq345A/volaifB8mRU6fdu0.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream103","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/hasunosora/live-event/image.php?img_path=/lovelive/jp/live/2026/10/14/1002/NO6lMUJ2hAeORI8v/yFhc5NZGMFBB1vEJ.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream103","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/hasunosora/live-event/image.php?img_path=/lovelive/jp/live/2026/10/14/1002/6gxN01HfUXCM7EiS/xpANcscp98GhAIlR.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream103","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/hasunosora/live-event/image.php?img_path=/lovelive/jp/live/2026/10/14/1002/AeNaTfsCTqI59QLS/rieCSDVwFiaCCTC1.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream103","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/hasunosora/live-event/image.php?img_path=/lovelive/jp/live/2026/10/14/1002/Kp9EC9LfaR8qJi9Q/oGV1EaisFB53RGpJ.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream103","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/hasunosora/live-event/image.php?img_path=/lovelive/jp/live/2026/10/14/1002/lNHUIzXZXQAhdHYl/x8myZOxyvc9U4Ryq.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream103","checked_on":"2026-10-30"}]','[]','[{"title":"场次与出演差异","text_zh":"1月23日16:00入场、17:00开演；24日14:30入场、15:30开演。花宫初奈仅第二天出演。","evidence_ja":"【日程】\nDay.1 2027年1月23日(土) 16:00開場／17:00開演\nDay.2 2027年1月24日(日) 14:30開場／15:30開演\n【会場】\n東京・日本武道館\n【出演】\n蓮ノ空女学院スクールアイドルクラブ\n楡井希実（日野下花帆役）、花宮初奈（乙宗 梢役）、野中ここな（村野さやか役）、佐々木琴子（夕霧綴理役）、菅 叶和（大沢瑠璃乃役）、月音こな（藤島 慈役）、櫻井陽菜（百生吟子役）、葉山風花（徒町小鈴役）、来栖りん（安養寺姫芽役）、三宅美羽（セラス 柳田 リリエンフェルト役）、進藤あまね（桂城 泉役）\n※花宮初奈（乙宗 梢役）はDay.2 のみ出演となります。","id":"auto-70dd2d30c1a28bb3-rule-0","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream103","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"Day1附券","text_zh":"10月14日发行Extra单曲附券：10月14日12:00至11月8日23:59受理；每序列号最多2张，11月14日13:00公布结果，中选后至11月17日21:00付款。均为日本时间。","evidence_ja":"★お申込み対象：Day.1 2027年1月23日（土）公演\n2026年10月14日（水）発売\n蓮ノ空女学院スクールアイドルクラブ Extraシングル\n「タイトル未定」\n封入申込券にて受付\n----------\n■受付期間：2026年10月14日（水）12:00～11月8日（日）23:59\n■当落発表：2026年11月14日（土）13:00～\n■入金期間：2026年11月14日（土）13:00～11月17日（火）21:00\n※枚数制限：『シリアルNo.』1つにつき、Day.1公演に2枚までお申込み可能\n----------","id":"auto-70dd2d30c1a28bb3-rule-1","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream103","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"Day2附券","text_zh":"9月25日发行电影Bloom Garden Party BD特装限定版附券：9月25日12:00至11月8日23:59受理，每序列号最多2张；结果及付款时间与Day1相同。","evidence_ja":"★お申込み対象：Day.2 2027年1月24日（日）公演\n2026年9月25日（金）発売\n『映画 ラブライブ！蓮ノ空女学院スクールアイドルクラブ Bloom Garden Party』Blu-ray（特装限定版）\n封入申込券にて受付\n----------\n■受付期間：2026年9月25日（金）12:00～11月8日（日）23:59\n■当落発表：2026年11月14日（土）13:00～\n■入金期間：2026年11月14日（土）13:00～11月17日（火）21:00\n※枚数制限：『シリアルNo.』1つにつき、Day.2公演に2枚までお申込み可能\n----------","id":"auto-70dd2d30c1a28bb3-rule-2","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream103","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"票价及U-20","text_zh":"指定席13,000日元，U-20票6,500日元；U-20计划随一般销售开放，参加者和同行者须在演出当天未满20岁并接受年龄核实，每人每场最多2张。","evidence_ja":"【チケット料金】\n全席指定：13,000円（税込）\nU-20割引チケット：6,500円（税込）\nアリーナアップグレードチケット（グッズ付き）：＋13,000円\n----------\n＜U-20割引チケットについて＞\n本公演は、20歳未満の方にもご参加いただきやすくするため、対象の方に向け「U-20割引チケット」を販売いたします。\n・ 公演当日時点で20歳未満の方が購入できるチケットとなります。\n・一般発売に合わせ販売予定です。枚数には限りがございますので、あらかじめご了承ください。\n・当日はご入場にあたり、年齢を確認できる身分証明書を確認させていただきます。\n・U-20割引チケットはお一人様1公演につき2枚までお申込みいただけますが、同行者の方も公演当日時点で20歳未満の方に限ります。あらかじめご了承ください。\n----------","id":"auto-70dd2d30c1a28bb3-rule-3","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream103","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"升席不是门票","text_zh":"升席另加13,000日元，仅最速先行中选并完成付款的原申请者可申请；分两轮抽选，第二轮信用卡付款限定。不能把升席当作普通门票购买。","evidence_ja":"＜アップグレード受付（1次抽選）＞\n----------\n■受付期間：2026年11月21日（土）12:00～11月29日（日）23:59\n■当落発表：2026年12月5日（土）13:00～\n■入金期間：2026年12月5日（土）13:00～12月8日（火）21:00\n※支払い方法：クレジットカード・コンビニ／ATM・ネットバンキング（ペイジー）がお選びいただけます。\n----------\n＜アップグレード受付（2次抽選）＞\n----------\n■受付期間：2026年12月5日（土）12:00～12月13日（日）23:59\n■当落発表：2026年12月19日（土）13:00～\n※支払い方法：クレジットカードのみとなります。\n----------\n※受付URLは最速先行抽選でチケット購入済みの方でお申込ご本人様のみへイープラスよりメールでご案内いたします。\nメールが届かない場合はお申込ご本人様のイープラスサイト内「申込み履歴（申込み状況照会）」の当選したチケットの詳細から受付URLをご確認いただけます。\n▼申込み履歴（申込み状況照会）\nhttps://eplus.jp/jyoukyou/\n※同行者様には受付URLのご案内はいたしません。","id":"auto-70dd2d30c1a28bb3-rule-4","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream103","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"身份核实","text_zh":"申请者及同行者都须登记人脸照片，并携带带照片的官方身份证件；3岁以上收费，票价外另收手续费。","evidence_ja":"●注意事項●\n※3歳以上有料\n※お申込み時にイープラスの会員登録（無料）が必要です。\n※必ず受付画面にて、注意事項をご確認の上、お申込みください。\n※抽選販売分は先着順での受付ではございませんので、受付期間内にお申込みください。当落および座席などは、先着順ではなく、期間内にお申込みいただいた中から抽選で決定いたします。\n※お席に関してのお問合せには、お答えできません。\n※お申込み内容の変更・取消しは受付期間中のみおこなえます。当選後の変更・取消し(購入辞退)は一切お受けできませんのでご注意ください。\n※チケット代金の他に各種手数料が必要となります。\n※アルコール類の持込、及び飲酒してのご入場は固くお断りいたします。\n※開場・開演時間、出演者は諸事情により変更になる場合がございます。それに伴うチケット代・交通費等の払い戻しはいたしません。あらかじめご了承ください。\n※ご来場のお客様におかれましては、公演における注意事項を必ずお読みいただき、遵守くださいますようお願いいたします。ご協力いただけない場合、ご入場いただけない可能性もございますので、あらかじめご了承ください。\n※顔認証入場システムを利用したチケット販売のため、顔写真登録が必要となります。必ず来場者ご本人様がお申込みください。（チケットを複数枚購入される場合、同行者の顔写真登録も必要となります。）\n※顔認証入場システムでご本人と判断できない場合、顔写真付きの公的身分証でご本人確認をさせていただきますので、必ずご持参ください。","id":"auto-70dd2d30c1a28bb3-rule-5","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/live-event/live_detail.php?p=LLDream103","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","两天须使用不同附券商品。"]','published','2026-10-30T14:10:44.737Z','2026-10-30T14:10:44.737Z') on conflict do nothing;
