insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-12799e94fdc2df29','official-12799e94fdc2df29','『イキヅライブ！ LOVELIVE! BLUEBIRD』のポップアップストア 「POP UP SHOP ～Winter♡Date～」 が東京アニメセンター in DNP PLAZA SHIBUYAにて開催決定！','人生不易部「Winter♡Date」涩谷快闪','快闪店','2026年11月13–29日在涩谷MODI 2楼东京Anime Center举办，11:00–19:00。首三天10:45–10:50发入场抽签整理券，非先到先得；每满3,000日元赠随机贴纸。','{"url":"https://www.lovelive-anime.jp/lovelive/jp/news/2026/10/16/1002/eplWX8YUqyUyAJ3d/pCqFGgknUEGHRr40.jpeg","alt":"人生不易部「Winter♡Date」涩谷快闪","source_url":"https://www.lovelive-anime.jp/lovehigh/news/detail.php?p=01_6679","checked_on":"2026-10-30"}','[{"url":"https://www.lovelive-anime.jp/lovelive/jp/news/2026/10/16/1002/eplWX8YUqyUyAJ3d/pCqFGgknUEGHRr40.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/lovehigh/news/detail.php?p=01_6679","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/lovelive/jp/news/2026/10/16/1002/W5XWdPG0DAZ4PNxy/7XlPoVQ8cT20PPrV.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/lovehigh/news/detail.php?p=01_6679","checked_on":"2026-10-30"}]','[]','[{"title":"日期与场馆","text_zh":"11月13–29日，11:00–19:00；东京涩谷MODI 2楼，营业时间与商场可能不同。","evidence_ja":"【 開催場所】 東京アニメセンター in DNP PLAZA SHIBUYA\n(東京都渋谷区神南1丁目21-3 渋谷MODI 2F)\n【開催期間】 2026年11月13日（金）～11月29日（日）\n【営業時間】 11:00～19:00\n※施設の営業時間とは異なります。\n※開催内容は予告なく変更になる場合がございます。","id":"auto-12799e94fdc2df29-rule-0","kind":"参加","source_url":"https://www.lovelive-anime.jp/lovehigh/news/detail.php?p=01_6679","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"限购","text_zh":"每笔结账：随机商品每款最多20件，非随机商品每款每种最多3件；限制可能调整。","evidence_ja":"・ランダム商品のご購入は、1会計につき各商品20個まで。\n・オープン商品のご購入は、1会計につき、各商品各種3個まで。","id":"auto-12799e94fdc2df29-rule-1","kind":"参加","source_url":"https://www.lovelive-anime.jp/lovehigh/news/detail.php?p=01_6679","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"赠品","text_zh":"每笔消费每满3,000日元（含税）获随机贴纸1张，全14种；出示EPOS卡再额外赠1张，不能选图，送完即止。","evidence_ja":"●購入特典\n1会計につき、3,000円（税込）お買い上げいただくごとに、「ランダムステッカー」（全14種）を\n1枚プレゼント！\n●エポスカード特典\nイベント会場でエポスカードをご提示いただいたお客様には、「ランダムステッカー」（全14種）を\n追加でもう1枚プレゼント！\n※特典は無くなり次第終了いたします。\n※「ランダムステッカー」の絵柄は選べません。","id":"auto-12799e94fdc2df29-rule-2","kind":"参加","source_url":"https://www.lovelive-anime.jp/lovehigh/news/detail.php?p=01_6679","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"首三天抽签入场","text_zh":"11月13–15日在涩谷MODI前10:45–10:50发券，约11:10在店门口和官方X公布抽签结果；按号码指定时间返回。10:50尚未排队则无法领券。","evidence_ja":"【 シャッフル入場に関するご案内 】\n●11月13日（金）~15日（日）についてはシャッフル入場を実施させていただきます。\n先着順ではございませんので予めご了承ください。\n・渋谷モディ館前にて整理券を配布いたします。\n整理券配布予定時間：10:45-10:50\n・11:10頃に抽選結果を東京アニメセンター入口および東京アニメセンター公式X（@anime_tokyo）にて発表いたします。\n・お手持ちの整理券番号の指定時刻に、再度お集まりください。\n・整理券をご希望の方は、配布開始時間（10:45）にお集まりくださいますようお願いいたします。\n※ご注意\n・10:50の段階でお並びいただいていない場合は、シャッフル整理券をお渡しできません。","id":"auto-12799e94fdc2df29-rule-3","kind":"参加","source_url":"https://www.lovelive-anime.jp/lovehigh/news/detail.php?p=01_6679","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"同行与其他日期","text_zh":"无整理券者须等整理券时段结束后自由入场；同行者要同时入场则按各自号码最晚时段入场。其他日期遇拥挤也可能抽签或限流。","evidence_ja":"・整理券をお持ちでないお客様は、整理券枠がすべて終了した後の【フリー入場】からのご案内となります。\n・お連れ様と同時入場をご希望の場合は、皆様がお持ちの整理券番号の案内時間のうち一番遅い回にてご案内いたします。\n・シャッフル入場対象時間であっても、整理券をお持ちの方がすべて入場されたあとはフリー入場とさせていただきます。\n・上記の日程以外でも、店内へのご入場をお待ちいただいているお客様が多数いらっしゃる場合は入場順の抽選、入場制限を行う場合がございます。","id":"auto-12799e94fdc2df29-rule-4","kind":"参加","source_url":"https://www.lovelive-anime.jp/lovehigh/news/detail.php?p=01_6679","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"通販区别","text_zh":"网上预订11月24日18:00至12月7日23:59，日本时间；预计2027年1月底起发货，通販没有购物贴纸或EPOS特典。","evidence_ja":"■WEB通販について\nバンダイナムコフィルムワークス公式通販サイトA-on STOREにて、11月24日（火）18時から12月7日（月）23時59分まで、本イベント商品の通販予約受付を実施いたします。\n【サイトURL】 https://a-onstore.jp/shop/winter-date/\n【受注期間】 2026年11月24日（火）18:00～12月7日（月）23:59\n【お届け予定日】 2027年1月末ごろより順次お届け予定\n※A-on STOREページは11月24日（火）18時にオープンとなります。\n※商品は後日お届けになります。\n※通販では購入特典、エポスカード特典はございません。","id":"auto-12799e94fdc2df29-rule-5","kind":"参加","source_url":"https://www.lovelive-anime.jp/lovehigh/news/detail.php?p=01_6679","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","11月13–15日10:45–10:50发抽签整理券，非先到先得；约11:10公布结果。其余日期也可能按拥挤情况抽签或限流。"]','published','2026-10-30T14:10:44.737Z','2026-10-30T14:10:44.737Z') on conflict do nothing;
