insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-27cc406bf0a3900e','official-27cc406bf0a3900e','学園アイドルマスター LIVE TOUR -標- ファイナル公演','学园偶像大师 LIVE TOUR「标」最终公演','音乐和声优活动','2026年11月7、8日在横滨K Arena举办，两天均计划15:30入场、17:00开演（日本时间）。本页仅为演出概要，票务价格、申请与余票须另查官方TICKET页面。','{"url":"https://idolmaster-official.jp/live_event/gkmas_livetour_shirube/assets/images/common/btn_fukui.png","alt":"学园偶像大师 LIVE TOUR「标」最终公演","source_url":"https://idolmaster-official.jp/live_event/gkmas_livetour_shirube/information/final.php","checked_on":"2026-10-30"}','[{"url":"https://idolmaster-official.jp/live_event/gkmas_livetour_shirube/assets/images/common/btn_fukui.png","alt":"福井公演","source_url":"https://idolmaster-official.jp/live_event/gkmas_livetour_shirube/information/final.php","checked_on":"2026-10-30"},{"url":"https://idolmaster-official.jp/live_event/gkmas_livetour_shirube/assets/images/common/btn_fukuoka.png","alt":"福岡公演","source_url":"https://idolmaster-official.jp/live_event/gkmas_livetour_shirube/information/final.php","checked_on":"2026-10-30"},{"url":"https://idolmaster-official.jp/live_event/gkmas_livetour_shirube/assets/images/common/btn_iwate.png","alt":"岩手公演","source_url":"https://idolmaster-official.jp/live_event/gkmas_livetour_shirube/information/final.php","checked_on":"2026-10-30"},{"url":"https://idolmaster-official.jp/live_event/gkmas_livetour_shirube/assets/images/common/btn_final.png","alt":"ファイナル公演","source_url":"https://idolmaster-official.jp/live_event/gkmas_livetour_shirube/information/final.php","checked_on":"2026-10-30"},{"url":"https://idolmaster-official.jp/live_event/gkmas_livetour_shirube/assets/images/common/img_final.webp","alt":"ファイナル公演 ビジュアル","source_url":"https://idolmaster-official.jp/live_event/gkmas_livetour_shirube/information/final.php","checked_on":"2026-10-30"}]','[]','[{"title":"日期与场馆","text_zh":"11月7、8日，两天均15:30入场17:00开演，K Arena横滨。","evidence_ja":"開催日時\n2026年11月7日(土) 15：30開場／17：00開演 (予定)\n2026年11月8日(日) 15：30開場／17：00開演 (予定)\n場所\nKアリーナ横浜","id":"auto-27cc406bf0a3900e-rule-0","kind":"参加","source_url":"https://idolmaster-official.jp/live_event/gkmas_livetour_shirube/information/final.php","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"变更可能","text_zh":"出演人员与时间可能调整，突发伤病可能导致当日出演取消或变更，不应因此把整场演出标为取消。","evidence_ja":"※出演者および各公演時間等は予告なく変更になる場合がございます。","id":"auto-27cc406bf0a3900e-rule-1","kind":"参加","source_url":"https://idolmaster-official.jp/live_event/gkmas_livetour_shirube/information/final.php","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","本页只公布两日演出概要，15:30开场、17:00开演（日本时间，预定）。票价、申请与余票须查官方TICKET页；未确认可购票。"]','published','2026-10-30T14:10:44.737Z','2026-10-30T14:10:44.737Z') on conflict do nothing;
