insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-35517508cbd07a8f','official-35517508cbd07a8f','カクダイ製菓（愛知県名古屋市）が製造・販売する「クッピーラムネ」と「ラブライブ！シリーズ」のコラボレーション決定！！','Love Live! × クッピーラムネ 名古屋PremiumShop联动','快闪店','2026年11月13日至16日，名古屋AEON MALL Nagoya Dome前2层美食广场旁桥廊举行PremiumShop联动销售，10:00–21:00营业。商品详情、库存及入场安排需查看官方专题和官方X；网店不作为现场活动地点。','{"url":"https://www.lovelive-anime.jp/lovelive/jp/news/2026/10/28/1002/S9j3ef0Xv5bIH8WK/oyBor1Vdj8JIbCrK.jpeg","alt":"Love Live! × クッピーラムネ 名古屋PremiumShop联动","source_url":"https://www.lovelive-anime.jp/lovehigh/news/detail.php?p=01_6729","checked_on":"2026-10-30"}','[{"url":"https://www.lovelive-anime.jp/lovelive/jp/news/2026/10/28/1002/S9j3ef0Xv5bIH8WK/oyBor1Vdj8JIbCrK.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/lovehigh/news/detail.php?p=01_6729","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/lovelive/jp/news/2026/10/27/1002/pNJxcCi9f6z5GmSd/Elg0lrIDL6sICAfH.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/lovehigh/news/detail.php?p=01_6729","checked_on":"2026-10-30"}]','[]','[{"title":"地点与营业时间","text_zh":"店内销售点在AEON MALL名古屋Dome前2层美食广场旁桥廊，11月13日至16日10:00–21:00（日本时间）。","evidence_ja":"◆イオンモールナゴヤドーム前\n開催場所：〒461-0048 愛知県名古屋市東区矢田南4丁目102番3号\nイオンモールナゴヤドーム前 2階フードコート横ブリッジ\nイオンモールナゴヤドーム前 HP： https://www.aeon.jp/sc/nagoyadomemae/\n開催期間：2026年11月13日(金)～11月16日(月)\n営業時間：10:00～21:00\n","id":"auto-35517508cbd07a8f-rule-0","kind":"参加","source_url":"https://www.lovelive-anime.jp/lovehigh/news/detail.php?p=01_6729","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"库存与参加方式","text_zh":"品切及销售信息请查看PremiumShop官方X，尚未给出固定预约方法、限购和特典门槛，不推断有货或自由入场。","evidence_ja":"※品切れや販売情報はこちらよりご確認ください。","id":"auto-35517508cbd07a8f-rule-1","kind":"参加","source_url":"https://www.lovelive-anime.jp/lovehigh/news/detail.php?p=01_6729","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","本公告未公布预约细则，不能认定无需预约、现场可入场或有库存；请查看官方活动入口。"]','published','2026-10-30T14:10:44.737Z','2026-10-30T14:10:44.737Z') on conflict do nothing;
