insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-04c73e062516c03a','official-04c73e062516c03a','NAKAMACHI ARALE LIVE 2026「RESONEXT」','仲町あられ「RESONEXT」（一般销售已结束）','音乐和声优活动','2026年12月24日在东京大手町三井Hall举办昼夜两场，一般指定席6,600日元、附特典指定席9,900日元（含税）。官网本轮明确标记一般销售已结束，不能继续视为开放受理；后续售票未公告。附特典票的拍立得风卡于终演后亲手交付。','{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/09/21095234/e2e6ec4f-026ee792-c19c4bde-e4861033.jpg","alt":"仲町あられ「RESONEXT」（一般销售已结束）","source_url":"https://bang-dream.com/events/nakamachiarale_live2026/","checked_on":"2026-10-30"}','[{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/09/21095234/e2e6ec4f-026ee792-c19c4bde-e4861033.jpg","alt":"NAKAMACHI ARALE LIVE 2026「RESONEXT」","source_url":"https://bang-dream.com/events/nakamachiarale_live2026/","checked_on":"2026-10-30"},{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/09/24162640/62cc68bd-b219e096-3ce0d867-14f7ff4e.png","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://bang-dream.com/events/nakamachiarale_live2026/","checked_on":"2026-10-30"},{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/09/24162742/4389b2e7-48c59d23-4d29d329-7ad979c8.png","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://bang-dream.com/events/nakamachiarale_live2026/","checked_on":"2026-10-30"}]','[]','[{"title":"一般销售已结束","text_zh":"官网现明确标记一般销售「受付終了」。原10月3日12:00起的先着电子票销售已结束，原限每人2张；不再把没有截止时刻解释成开放中。","evidence_ja":"一般発売（受付終了）\n受付期間：2026年10月3日(土) 12:00 ～\n※先着順・上限数に達し次第終了\n※スマチケのみの受付となります。\n※お一人様につき2枚までお申込みいただけます。","id":"auto-04c73e062516c03a-rule-0","kind":"参加","source_url":"https://bang-dream.com/events/nakamachiarale_live2026/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"特典领取","text_zh":"附特典门票赠特制拍立得风卡，演出结束后由仲町あられ亲手交付。","evidence_ja":"※終演後、仲町あられより直接お渡しいたします。","id":"auto-04c73e062516c03a-rule-1","kind":"参加","source_url":"https://bang-dream.com/events/nakamachiarale_live2026/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"场次与票价","text_zh":"昼场13:15入场14:00开演，夜场18:30入场19:15开演。特典指定席9,900日元，一般6,600日元含税，原每票种每人合计2张。","evidence_ja":"日程\n2026年12月24日(木)\n昼の部 開場：13:15／開演：14:00（予定）\n夜の部 開場：18:30／開演：19:15（予定）\n会場\n大手町三井ホール\n出演\n仲町あられ（夢限大みゅーたいぷ）\nチケット\n料金\n特典付き指定席：9,900円(税込）\n一般指定席：6,600円(税込)\n※各券種、お一人様合計2枚までお申込みいただけます。","id":"auto-04c73e062516c03a-rule-2","kind":"参加","source_url":"https://bang-dream.com/events/nakamachiarale_live2026/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"年龄、有效票与退款","text_zh":"学龄前儿童不得入场，一票一人，仅票面场次及会场有效。除取消或延期外不退票。","evidence_ja":"・未就学児の入場はできません。\n・チケットは券面に記載の公演日、会場でのみ有効となります。\n・1枚のチケットを複数のお客様で使用することはできません（チケット1枚につきお客様1名様のみのご入場となります）。\n・公演中止、延期の場合以外でのチケットの払い戻しはいかなる理由でも行いません。予めご了承ください。","id":"auto-04c73e062516c03a-rule-3","kind":"参加","source_url":"https://bang-dream.com/events/nakamachiarale_live2026/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"身份证明与禁止转售","text_zh":"不得转售或转让，可能检查所有入场者身份；须带1份官方照片证件或照片学生证。无照片学生证须另加本人保险证或其复印件，共2件。仅通过官方电子票功能分配给同行者不在禁止范围。","evidence_ja":"2. チケットの転売・譲渡について\nチケットの転売・譲渡は、いかなる場合も固く禁止しております。\n転売対策のため、入場前に全てのお客様についてご本人様確認を実施させていただく場合がございますので、公的な顔写真付身分証明書1点（免許証・パスポート・在留カード・障害者手帳・顔写真付クレジットカード・顔写真付住民基本台帳カード・マイナンバーカードなど）または顔写真付学生証（生徒手帳・学生手帳）1点を必ずご準備ください。\n顔写真付でない学生証（生徒手帳・学生手帳）をお持ちの方は、顔写真付でない学生証（生徒手帳・学生手帳）1点に加え、ご本人名義の保険証または保険証の写し1点の合計2点をご用意の上、ご来場ください。\n身分証をご提示いただけない場合、入場をお断りする場合がございます。\n※イープラス「スマチケ」など、電子チケットの分配機能を用いた同行者への分配は問題ございません。","id":"auto-04c73e062516c03a-rule-4","kind":"参加","source_url":"https://bang-dream.com/events/nakamachiarale_live2026/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"应援与危险物限制","text_zh":"禁止危险物、非市售或改造手灯、30cm以上及过亮/连结手灯。即使市售也不可挥扔、口衔、单手4根以上、频闪或在头顶持续旋转；不得高举板/扇/玩偶挡人。禁止攀爬、过度跳跃、冲撞、潜水、骑肩、旗帜横幅及发声应援用品。","evidence_ja":"・サイリウム、ペンライトのうち市販されていないもの、改造品、30㎝以上の長さのあるもの、市販されているサイリウム・ペンライト商品のうち光量が著しく大きいもの、連結ペンライト、誘導灯やその他の照明器具を持ち込むこと。なお、入場時の手荷物検査及び会場内にてこれらの物品を係員が発見した場合には、その場でご自身にて破棄していただくか、破棄いただけない場合は入場をお断り、または途中退場していただきます。\n・市販されているサイリウム・ペンライトであっても、振り回す・投げる・口にくわえる・片手に4本以上持つ ・光の点滅を繰り返す・頭上で執拗に回転させるなどして、他のお客様の迷惑になり得る態様で利用すること。\n・持ち手を含まず、面の部分が直径30㎝以上のうちわやメッセージボードを、ご自身の胸の高さ以上の位置で持つこと及び当該うちわやメッセージボードを振り回すなどして、他のお客様の迷惑になり得る態様で利用すること。\n・ぬいぐるみ・おもちゃ等イベント中に使用することを想定されていないグッズ類を、ご自身の胸の高さ以上の位置で持つこと及び当該グッズ類を振り回すなどして、他のお客様の迷惑になり得る態様で利用すること。\n・座席・柵に上ること、座席、柵からジャンプすること。\n・イベントの妨げとなるような、大声を張り上げる・奇声を上げること。\n具体例：通称 家虎、MIX、ワールドカオスと呼ばれる行為等\n・イベントの妨げとなるような大きな音を出すこと、腕を振り回すこと、過度なジャンプ行為。\n具体例：通称 オタ芸と呼ばれる行為等\n・モッシュ・ダイブ・肩車・一定方向に押し寄せること。\n・旗・横断幕・音の出る応援グッズを持ち込むこと。なお、入場時の手荷物検査及び会場内にてこれらの物品を係員が発見した場合には、その場でご自身にて破棄していただくか、破棄いただけない場合は入場をお断り、または途中退場していただきます。\n・正規の手段以外の手段により取得されたチケットでのご入場。","id":"auto-04c73e062516c03a-rule-5","kind":"参加","source_url":"https://bang-dream.com/events/nakamachiarale_live2026/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"安检与违规处理","text_zh":"入场有行李检查，请预留时间。违规可能被核验证件、拒绝入场或退场，不退费用，并可能被长期禁止参加相关活动；严重行为可能报警或采取法律措施。","evidence_ja":"(3) 手荷物検査の強化\n当社が持込を禁止する物品の検査を行うため、イベント入場時の手荷物検査を徹底いたします。\n手荷物検査の実施に伴い、入場時にお時間を要する場合がございますので、時間に余裕をもってイベントへご来場いただけますようお願いいたします。\n(4) 禁止行為を発見した場合の対応\nイベントにおいて禁止行為及びこれに類する行為が発見された場合には、身分証の提示を求めるほか、係員により入場をお断りする、または退場していただくなど厳正に対処いたします。\nなお、イベント中に禁止行為及びこれに類する行為が頻発した場合にはイベントを中断又は中止する場合があります。\n当社は、 禁止行為が認められたお客様については、以後、当社並びに株式会社ブシロード及びその関連会社が関連するすべてのイベント（お渡し会、朗読会、舞台等形式・名称を問いません）への出入りを無期限で禁止させていただきます。万一、入場が確認された場合には、その場で直ちに退場いただきます。禁止行為が認められたお客様が入場不能・退場となった場合でも、イベントチケット代金等の費用の返金には一切応じません。\nまた、 当社は、禁止行為の様態により、禁止行為を行ったお客様に対し、警察への通報、法的措置（民事・刑事を問いません）その他当社が必要と判断する対応を行います。\n（5）免責","id":"auto-04c73e062516c03a-rule-6","kind":"参加","source_url":"https://bang-dream.com/events/nakamachiarale_live2026/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"拍摄与领取物品","text_zh":"原则上禁拍，终演后可在不妨碍他人的范围拍照，上传不得侵犯他人肖像。周边原则上当日在场领取，不接受事前事后寄送，漏领须当日提出；官方可能摄制现场。","evidence_ja":"・グッズ付きチケットをご購入された場合、グッズは原則として会場でのお渡しとなります。いかなる理由でも事前または事後の発送は受け付けておりませんので予めご了承ください。グッズのお受け取り忘れにつきましても、開催当日のご申告のみ対応させていただきます。後日のご連絡にはお応えいたしかねますので、グッズはお忘れなくお受け取りください。その他入場時等の配布物につきましても同様とさせていただきます。\n・会場内での写真撮影は原則として禁止しておりますが、終演後に限り、他のお客様のご迷惑にならない範囲で撮影いただくことが可能です。なお、他のお客様の顔が写っている画像をSNSなどインターネットに掲載された場合は肖像権の侵害となる恐れがありますので、十分にご注意ください。\n・当日は収録等のため、会場内にカメラを設置する場合がございます。後日公開の映像・写真にお客様が映り込むことがございますので、予めご了承ください。","id":"auto-04c73e062516c03a-rule-7","kind":"参加","source_url":"https://bang-dream.com/events/nakamachiarale_live2026/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"酒类与礼物","text_zh":"馆内不售酒，也不得携带酒类；不接收礼物和粉丝来信。","evidence_ja":"・会場内ではアルコールの販売はございません。また、アルコールの持ち込みは禁止とさせていただきます。\n・プレゼント・ファンレターはお控えください。プレゼントボックスも設置は致しません。","id":"auto-04c73e062516c03a-rule-8","kind":"参加","source_url":"https://bang-dream.com/events/nakamachiarale_live2026/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","已知一般先着销售和先行均已结束，官网未给出实际售罄时刻或后续轮次，不能伪造截止时间；后续售票方式未知。"]','published','2026-10-30T14:10:44.737Z','2026-10-30T14:10:44.737Z') on conflict do nothing;
