insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-1c624082c33b649c','official-1c624082c33b649c','ラブライブ！サンシャイン!! 第５回沼津地元愛まつり','Aqours 第五届沼津地元爱祭','其他联动','2027年3月20–22日在沼津キラメッセぬまづ举办，每日昼夜两场、出演成员不同。最新一轮官方先行抽选已于2026年10月25日23:59（日本时间）截止，10月31日公布结果。同期地元爱物产展另设会场，细节尚待公布。','{"url":"https://www.lovelive-anime.jp/uranohoshi/live/image.php?img_path=/lovelive/jp/live/2026/06/30/1002/g4jfzkV9elMRjdWG/xMliz5BPocxHQzNT.jpeg","alt":"Aqours 第五届沼津地元爱祭","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=jimoai5th","checked_on":"2026-10-30"}','[{"url":"https://www.lovelive-anime.jp/uranohoshi/live/image.php?img_path=/lovelive/jp/live/2026/06/30/1002/g4jfzkV9elMRjdWG/xMliz5BPocxHQzNT.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=jimoai5th","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/uranohoshi/live/image.php?img_path=/lovelive/jp/live/2026/07/24/1002/IIwiPe4JtKjKxyID/UExbot6o7UkXnczZ.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=jimoai5th","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/uranohoshi/live/image.php?img_path=/lovelive/jp/live/2026/07/24/1002/roua832LtTWFqgRW/v89pV4rUdTPdYMwF.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=jimoai5th","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/uranohoshi/live/image.php?img_path=/lovelive/jp/live/2026/07/24/1002/6AZoV3zwMRijcepL/8h7QelWnAdjXRtNr.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/uranohoshi/live/live_detail.php?p=jimoai5th","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/uranohoshi/live/image.php?img_path=/lovelive/jp/live/2026/10/30/1003/sZg7iYqvHMLpIdBu/5d3EDfeuYRxms5g5.jpeg","alt":"官方公告配图（图中文