insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-30fb7128504cc0da','official-30fb7128504cc0da','シークフェルト音楽学院 トーク＆バラエティイベント 伝説の補習授業！？','西克菲尔特音乐学院谈话综艺活动「传说中的补习课！？」','音乐和声优活动','2026年11月1日在横滨Landmark Hall举行，昼场14:00、夜场18:00，预计提前1小时开场。全席指定8,000日元含税，另需现金600日元饮料费。官网已列一般销售入口但不能证明当前余票；物贩时段、随机特典、限购与参加限制见下。日本时间。','{"url":"https://revuestarlight.com/wordpress/wp-content/uploads/2026/06/30184200/7aadb0dbfbebb02c45a2e636ec0c0803.png","alt":"西克菲尔特音乐学院谈话综艺活动「传说中的补习课！？」","source_url":"https://revuestarlight.com/event/11083/","checked_on":"2026-10-30"}','[{"url":"https://revuestarlight.com/wordpress/wp-content/uploads/2026/06/30184200/7aadb0dbfbebb02c45a2e636ec0c0803.png","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://revuestarlight.com/event/11083/","checked_on":"2026-10-30"},{"url":"https://revuestarlight.com/wordpress/wp-content/uploads/2026/06/26175949/cade73b945a9bea208b85a3522614df3-scaled.jpg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://revuestarlight.com/event/11083/","checked_on":"2026-10-30"},{"url":"https://revuestarlight.com/wordpress/wp-content/uploads/2026/06/26175938/RS_tokuten_blomide_ari.jpg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://revuestarlight.com/event/11083/","checked_on":"2026-10-30"}]','[]','[{"title":"票价与饮料费","text_zh":"全席指定8,000日元（含税）；入场另付600日元饮料费，饮料费仅收现金。","evidence_ja":"全席指定 8,000円(税込)\n※入場時別途ドリンク代600円が必要となります。\n※ドリンク代のお支払いは現金のみとなります。","id":"auto-30fb7128504cc0da-rule-0","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"售票与旧轮次","text_zh":"官网列出10月10日10:00起一般销售，售完即止；该段未写年份，也未明确抽选或先着类型，因此不生成精确开放时间。7月24日至8月23日的先行、9月7日至21日的二次先行均已结束。仅表示公告内容，不能证明现在有票。官方购票入口：https://eplus.jp/revuestarlight_1101/ 。","evidence_ja":"■一般販売\n10月10日(土)10:00〜なくなり次第販売終了\n購入はこちらから→ https://eplus.jp/revuestarlight_1101/\n■ チケットプレイガイド先行 →終了しました\n7月24(金) 18:00〜8月23日(日)23:59\n申し込みはこちら→ https://eplus.jp/revuestarlight_1101/\n■ 二次先行 →終了しました\n9月7日(月)12:00〜9月21日(月)23:59","id":"auto-30fb7128504cc0da-rule-1","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"来场特典","text_zh":"来场赠1款10枚入贴纸组及1张Weiß Schwarz Blau PR卡，昼夜共通；图为示意，可能在其他活动再次派发。","evidence_ja":"来場者特典\nフレークシールセット1種（10枚入り）\nヴァイスシュヴァルツブラウPRカード1枚\n※画像はイメージです\n※後日他のイベントでも配布する可能性がございます。\n※特典は昼夜共通となります","id":"auto-30fb7128504cc0da-rule-2","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"物贩特典门槛","text_zh":"同笔消费每满3,000日元含税，从10款生写真中随机赠1张；6,000/9,000日元对应2/3张。不可合并不同收据，送完即止，取得10张也不保证集齐。","evidence_ja":"会場物販購入特典として、1会計3,000円(税込)購入ごとに特典ブロマイド全10種からランダムで1枚プレゼント！\n※例：6,000円購入いただいた場合2枚、9,000円購入いただいた場合3枚となります。\n※別会計レシートの合算はいたしかねます。\n※特典はなくなり次第終了となります。予めご了承ください。\n※10枚分のお渡しでもコンプリートの保証はいたしかねますので予めご了承ください。","id":"auto-30fb7128504cc0da-rule-3","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"物贩时间与入场票","text_zh":"11月1日先行物贩10:30–12:30、昼场结束后至16:30；开场中物贩13:00–14:00及17:00–18:00，仅限持对应场次票者。夜场结束后不销售；开场变动会影响销售时间。","evidence_ja":"・販売日時\n2026年11月1日(日)\n先行物販：10:30-12:30, 昼公演終了後-16:30\n開場中物販：13:00-14:00(昼公演), 17:00-18:00(夜公演)\n※開場時間が変更になる場合は開場中物販の開始時間も変更になります。\n※開場中物販は該当の回のチケットをお持ちのお客様のみご利用いただけます。\n※夜公演終演後の販売はございません。","id":"auto-30fb7128504cc0da-rule-4","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"库存与整理券","text_zh":"昼场库存分配至先行物贩及昼场结束后物贩；夜场库存自夜场开场中物贩起销售。各有数量限制，现场可能为安全发随机整理券；销售时间或内容可能更改、停止。","evidence_ja":"※販売の開始、終了時間等は当日の状況によって変更する場合がございます。\n※予告なく変更・販売中止となる場合があります。予めご了承ください。\n※商品在庫は各公演で振り分けがございます。\n昼公演分在庫：先行物販から昼公演終了後物販まで\n夜公演分在庫：夜公演開場中物販から販売終了まで\n※各公演分ともに数に限りがございますので、あらかじめご了承ください。\n※状況によってはお客様やスタッフの安全を考慮し、ランダム整理券を発行する場合がございます。","id":"auto-30fb7128504cc0da-rule-5","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"限购","text_zh":"每人每次结账每款最多3件；交易类商品最多3BOX或对应PACK数量；胶囊商品每种最多10次，现场可能调整。","evidence_ja":"・ご購入制限\nお一人様1会計あたり各種【3個まで】のご購入とさせていただきます。\n※トレーディング商品につきましては3BOX(相当分PACK数)までとなります。\n※カプセル商品は1種につき10回までとなります。\n※当日の状況によっては、急遽購入数制限を変更する場合がございます。","id":"auto-30fb7128504cc0da-rule-6","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"付款及退换","text_zh":"物贩可现金、所列信用卡和二维码付款，信用卡仅一次付清。瑕疵品仅限购买当天会场换货，结账后非瑕疵品不可退换退款。","evidence_ja":"その他注意事項\n※お会計は現金のほか、以下が利用可能です。\n・クレジットカード決済【VISA/Mastercard/JCB/Diners/AmericanExpress/Discover】\n・QRコード決済【PayPay/au PAY/d払い/Alipayなど】\n※クレジットカードのお支払い方法は「一括払い」のみとさせていただきます。\n※貴重品は個人の責任において管理をお願いいたします。盗難紛失等は責任を負いかねますので十分ご注意ください。\n※ デザイン・仕様は変更となる場合がございます。予めご了承ください。\n※不良品の交換は、当日お買い上げいただいた会場でのみ対応させて頂きます。\n※お会計後は、不良品以外の返品・返金・交換は出来ません。","id":"auto-30fb7128504cc0da-rule-7","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"排队与周边秩序","text_zh":"不得通宵、妨碍邻近设施；物贩购买后至开场前不要在会场附近等候。完售信息以官方Bushi_goods账号为准。","evidence_ja":"※会場付近での徹夜行為はご遠慮ください\n※会場近隣の施設・店舗への迷惑になる行為はご遠慮ください。\n※当日の混雑緩和のため、物販購入後から開場時間までの間は、会場付近での待機はご遠慮ください。\n当日の完売情報は、ブシロード イベントグッズ＆完売情報X（https://x.com/Bushi_goods）よりチェックしてください。","id":"auto-30fb7128504cc0da-rule-8","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"实名及禁止转售","text_zh":"应从正式渠道购票；门票及座位号不得转让或转售，否则可能作废、拒绝入场。发现或怀疑不当转售时可能核验身份，请携带身份证明。","evidence_ja":"■チケットの転売・譲渡について\n本公演のチケットは、ご購入時のご登録情報・ご入力情報が記載され、チケットや座席番号の譲渡・転売は一切禁止となります。\nチケットは正規販売ルート（興行主催者、主催者より正式に販売許可を得たプレイガイド、ファンクラブなど）でご購入いただきますようお願いいたします。\n譲渡・転売されたチケットや座席番号は無効となり、ご入場をお断りさせていただく場合もございますのでご注意ください。\nまた、営利目的の譲渡・転売等、チケットや座席番号に関する不正行為やそれを疑われる行為が発覚した場合には本人確認を実施させていただく場合がございますので、ご来場時には必ず本人確認書類をご持参ください。","id":"auto-30fb7128504cc0da-rule-9","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"年龄与安检","text_zh":"学龄前儿童不得入场；请勿Cosplay来场，入场可能检查随身行李。","evidence_ja":"・コスプレでのご来場は、周囲のお客様の影響を鑑み、ご遠慮頂きます様、お願いいたします。\n・未就学児入場不可となります。あらかじめご理解・ご了承お願い申し上げます。\n・入場時に手荷物検査を実施させて頂く場合がございます。ご協力をお願いいたします。\n・館内は禁煙です。","id":"auto-30fb7128504cc0da-rule-10","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"饮食及酒类","text_zh":"馆内禁烟、禁止饮食，补水只允许带盖饮料；不得携带酒类或醉酒来场。","evidence_ja":"・館内は禁煙です。喫煙の場合は近隣の喫煙所をご確認の上ご利用頂きますようお願いいたします。\n・館内での飲食は禁止です。水分補給は蓋つきのお飲み物のみ持ち込み可能です。\n・酒類の持ち込み、酒気を帯びた状態でのご来場は禁止とさせていただきます。","id":"auto-30fb7128504cc0da-rule-11","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"坐席与演出礼仪","text_zh":"须坐指定座位观看，含Live环节也禁止站立或换座；部分座位视线可能受设备影响。演出时摘帽并关闭手机、智能手表等发光电子设备；散场后不能使用洗手间。","evidence_ja":"・座席の移動は禁止です。必ず自分の席でご観覧ください。\n・イベント中はご着席をお願いいたします。ライブパート含め、スタンディングは禁止とさせていただきます。\n・お席によっては機材配置の関係で演出の一部が見えない、または見えにくい場合がございます。予めご了承ください。\n・上演中は特別な事情を除き、お帽子等の被り物は必ず外していただきますようお願い致します。\n・上演中は演出の妨げとなりますため、携帯電話、スマートフォン、スマートウォッチ等の光源となる電子機器は電源からお切りいただきますようお願い致します。\n・終演後はお手洗いはご利用いただけません。","id":"auto-30fb7128504cc0da-rule-12","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"应援用品","text_zh":"允许手灯、指环灯；禁用市售化学荧光棒、改造或长物、头戴及高举挡人。禁止其他应援用品（含扇子和应援板），禁止危险行为。","evidence_ja":"・本公演はペンライトやリングライトの使用が可能です。ペンライト・リングライトについては、市販されているサイリウムおよび改造や長物の使用、頭部につけるなどの行為は禁止とさせていただきます。\nまたペンライトやリングライト以外の応援グッズの使用は禁止です。\n常識の範囲内でのご使用をお願いします。また、頭より上の位置に上げる等、他のお客様のご迷惑となる行為はご遠慮ください。\n・うちわや応援ボードなど応援グッズの使用は禁止とさせていただきます 。","id":"auto-30fb7128504cc0da-rule-13","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"禁止拍摄与录音","text_zh":"观众不得拍照、录像、录音，违反可能没收数据并要求离场。","evidence_ja":"・場内でのスマートフォン・携帯電話・カメラ・テープレコーダー等による写真撮影、録音、録画は絶対におやめ下さい。万が一、行為を発見した場合はデータ没収のうえご退場して頂きます。\n・会場周辺（場内・場外含む）での座り込み","id":"auto-30fb7128504cc0da-rule-14","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"不接收花礼信件","text_zh":"不接收花篮、花艺、给演员和工作人员的礼物或信件，邮寄也谢绝。","evidence_ja":"■お花およびプレゼントについて\n本公演ではスタンド花・アレンジ花、共にお気遣いに感謝しつつ謹んで辞退申し上げます。 何卒ご理解の程よろしくお願い申し上げます。\n劇場に届いた場合、お断りさせていただきますのでご了承ください。\nまた、キャスト・スタッフへのプレゼントやお手紙のお預かりは、差し控えさせていただきます。\n郵送でお送りいただいた場合もお断りいたしますので、重ねてご理解の程よろしくお願い申し上げます。","id":"auto-30fb7128504cc0da-rule-15","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"行李与候场","text_zh":"无寄存处，行李箱等大件须提前寄存；不得在附近等演员、跟踪或妨碍交通，开演前及散场后不要在剧场周边逗留。","evidence_ja":"■迷惑行為について\n会場付近における出演者の入待ち、出待ち行為は禁止とさせていただきます。\n付きまといなどの行為を発見した際は、スタッフがお声掛けをさせていただく場合がございます。\n上記に限らず迷惑行為を行う方には、やむを得ず入場をお断りする可能性がございますので予めご了承ください。出演者が万全の状態でイベントを行えるようにご協力の程よろしくお願いいたします。\n会場周辺では通行の妨げや近隣施設の方の迷惑とならないよう、ご配慮をお願いいたします。特に公演開始前、公演終了後の劇場周辺での滞在はご遠慮ください。\n■会場内での注意事項\n・会場にクロークはございません。キャリーケースなどの大きなお荷物はあらかじめお預けの上ご来場いただきますようお願い致します。会場内でのお預かりは致しかねます。","id":"auto-30fb7128504cc0da-rule-16","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"变更与违规","text_zh":"内容、出演者可能无预告更改，天气等原因可能取消；须听从工作人员，违规可能无退款退场或导致活动中止。","evidence_ja":"・イベント内容、出演者は予告なしに変更する場合がございます。また、天候・出演者やその他の都合によりやむをえずイベントを中止する事がございます。予めご了承下さい。","id":"auto-30fb7128504cc0da-rule-17","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"轮椅与陪同","text_zh":"轮椅位有限，须于观看前2个营业日的营业时间内通过Bushiroad表单联系；陪同者也需要票，需要工作人员协助移动者同样需提前联系。服务时间为工作日10:00–18:00，节假日及年末年初除外。","evidence_ja":"■車椅子でのご来場について\n車椅子スペースのご用意はございますが、数に限りがございます。\n当日のお席までスムーズなご案内のため、ご観劇の2営業日前・営業時間内までに下記問い合わせフォームからご連絡をいただきますようお願いいたします。\n問い合わせ先：ブシロード\nhttps://bushiroad.com/contact\n付き添いのお客様につきましてもチケットが必要となります。\nまた、そのほかお座席までのご移動の際にスタッフによる手伝いをご希望のお客様も同様にご連絡をお願いいたします。\n■本イベントに関するお問い合わせ\n問い合わせ先：株式会社ブシロード\nhttps://bushiroad.com/contact\n営業時間：土日祝、年末年始除く、10:00～18:00","id":"auto-30fb7128504cc0da-rule-18","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"官方现场摄制","text_zh":"当天可能拍摄场内并用于放送、配信及复制发行。","evidence_ja":"・イベント当日、劇場内の模様を撮影し、放送・配信・複製頒布等する場合がございます。","id":"auto-30fb7128504cc0da-rule-19","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"违规处理","text_zh":"拒不遵从工作人员可能被要求退场且不退票；危险情况可能导致活动暂停或中止。","evidence_ja":"・係員の指示に従っていただけない場合は退場処分とさせていただくこともございます。その際のチケット代金の払い戻しは一切いたしかねます。以上の事が守られず器物破損及び事故につながる危険な場合は、イベントを一時中断、もしくは中止させていただきますのであらかじめご了承ください。","id":"auto-30fb7128504cc0da-rule-20","kind":"参加","source_url":"https://revuestarlight.com/event/11083/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"kind":"特典","title":"来场特典内容","evidence_ja":"フレークシールセット","text_zh":"来场特典包括图示贴纸组，图中列出10款。","id":"verified-image-026395dd1a151a5ba980","source_url":"https://revuestarlight.com/event/11083/","image_url":"https://revuestarlight.com/wordpress/wp-content/uploads/2026/06/30184200/7aadb0dbfbebb02c45a2e636ec0c0803.png","image_sha256":"dafb7cc392ed4a7285a37f96308851ffcaa2a0a15938c3bcb9527f87170953ab","checked_on":"2026-10-30"},{"kind":"特典","title":"贴纸各款一枚","evidence_ja":"各種1枚ずつ封入！","text_zh":"贴纸组每款各装1枚，不是随机只取其中一款。","id":"verified-image-5f8bd93f1bbbba3f0350","source_url":"https://revuestarlight.com/event/11083/","image_url":"https://revuestarlight.com/wordpress/wp-content/uploads/2026/06/30184200/7aadb0dbfbebb02c45a2e636ec0c0803.png","image_sha256":"dafb7cc392ed4a7285a37f96308851ffcaa2a0a15938c3bcb9527f87170953ab","checked_on":"2026-10-30"},{"kind":"特典","title":"PR卡数量","evidence_ja":"ヴァイスシュヴァルツブラウ PRカード1枚","text_zh":"另含1张Weiß Schwarz Blau PR卡。","id":"verified-image-5b10c9398eda474b1d39","source_url":"https://revuestarlight.com/event/11083/","image_url":"https://revuestarlight.com/wordpress/wp-content/uploads/2026/06/30184200/7aadb0dbfbebb02c45a2e636ec0c0803.png","image_sha256":"dafb7cc392ed4a7285a37f96308851ffcaa2a0a15938c3bcb9527f87170953ab","checked_on":"2026-10-30"},{"kind":"特典","title":"同笔满赠","evidence_ja":"1会計税込3,000円ご購入ごとに 特典ブロマイド全10種から ランダムで1枚プレゼント！","text_zh":"同笔消费每满3,000日元含税，从全部10款特典生写真中随机赠1张。","id":"verified-image-f54787160594d76a375f","source_url":"https://revuestarlight.com/event/11083/","image_url":"https://revuestarlight.com/wordpress/wp-content/uploads/2026/06/26175949/cade73b945a9bea208b85a3522614df3-scaled.jpg","image_sha256":"1f764c5f27b719ce2930d31904a9287069f2adfd5777e32340bc6a76e20cc2e9","checked_on":"2026-10-30"},{"kind":"特典","title":"特典送完即止","evidence_ja":"特典はなくなり次第終了となります。","text_zh":"特典数量有限，送完即止。","id":"verified-image-997aa4eb1e554a7abd80","source_url":"https://revuestarlight.com/event/11083/","image_url":"https://revuestarlight.com/wordpress/wp-content/uploads/2026/06/26175949/cade73b945a9bea208b85a3522614df3-scaled.jpg","image_sha256":"1f764c5f27b719ce2930d31904a9287069f2adfd5777e32340bc6a76e20cc2e9","checked_on":"2026-10-30"},{"kind":"购买","title":"镜面标志钥匙扣","evidence_ja":"ミラーアクリルロゴキーホルダー","text_zh":"镜面亚克力标志钥匙扣为1,100日元（含税，图示价格）。","id":"verified-image-c98f11417d21e0ddd2a1","source_url":"https://revuestarlight.com/event/11083/","image_url":"https://revuestarlight.com/wordpress/wp-content/uploads/2026/06/26175949/cade73b945a9bea208b85a3522614df3-scaled.jpg","image_sha256":"1f764c5f27b719ce2930d31904a9287069f2adfd5777e32340bc6a76e20cc2e9","checked_on":"2026-10-30"},{"kind":"购买","title":"角色钥匙扣","evidence_ja":"うさぎでんたろう＆シャンティーシャシャンティ アクリルキーホルダー","text_zh":"うさぎでんたろう＆シャンティーシャシャンティ亚克力钥匙扣为1,210日元（含税，图示价格）。","id":"verified-image-23b71783800649175ceb","source_url":"https://revuestarlight.com/event/11083/","image_url":"https://revuestarlight.com/wordpress/wp-content/uploads/2026/06/26175949/cade73b945a9bea208b85a3522614df3-scaled.jpg","image_sha256":"1f764c5f27b719ce2930d31904a9287069f2adfd5777e32340bc6a76e20cc2e9","checked_on":"2026-10-30"},{"kind":"购买","title":"演员立牌与生写真套装","evidence_ja":"アーティストアクリルスタンド","text_zh":"演员亚克力立牌每款1,870日元含税；下方生写真套装每款660日元含税，均以价目图所列为准。","id":"verified-image-aa689380a692bf767b24","source_url":"https://revuestarlight.com/event/11083/","image_url":"https://revuestarlight.com/wordpress/wp-content/uploads/2026/06/26175949/cade73b945a9bea208b85a3522614df3-scaled.jpg","image_sha256":"1f764c5f27b719ce2930d31904a9287069f2adfd5777e32340bc6a76e20cc2e9","checked_on":"2026-10-30"},{"kind":"购买","title":"交易贴纸PACK与BOX","evidence_ja":"トレーディングアーティスト ショートステッカーセット","text_zh":"交易演员短贴纸套装全20种，每PACK含2张、880日元含税；每BOX为10PACK、8,800日元含税。不据此保证全套。","id":"verified-image-f395a591362893a022e3","source_url":"https://revuestarlight.com/event/11083/","image_url":"https://revuestarlight.com/wordpress/wp-content/uploads/2026/06/26175949/cade73b945a9bea208b85a3522614df3-scaled.jpg","image_sha256":"1f764c5f27b719ce2930d31904a9287069f2adfd5777e32340bc6a76e20cc2e9","checked_on":"2026-10-30"},{"kind":"购买","title":"胶囊商品每单限次","evidence_ja":"1会計につき10回まで","text_zh":"两种胶囊亚克力吊饰分别标明每次结账最多10次，每次500日元含税；各全10种，每胶囊1个。","id":"verified-image-1ce812b2dd6b69eeb005","source_url":"https://revuestarlight.com/event/11083/","image_url":"https://revuestarlight.com/wordpress/wp-content/uploads/2026/06/26175949/cade73b945a9bea208b85a3522614df3-scaled.jpg","image_sha256":"1f764c5f27b719ce2930d31904a9287069f2adfd5777e32340bc6a76e20cc2e9","checked_on":"2026-10-30"},{"kind":"特典","title":"生写真尺寸与样张","evidence_ja":"サイズ L版サイズ","text_zh":"图示生写真为L版尺寸。","id":"verified-image-c86d571b009c0ac0f236","source_url":"https://revuestarlight.com/event/11083/","image_url":"https://revuestarlight.com/wordpress/wp-content/uploads/2026/06/26175938/RS_tokuten_blomide_ari.jpg","image_sha256":"86ffaffb6807eee97f2555e08a96c9b7102c3ced6e701eed17d55b70bf965b7d","checked_on":"2026-10-30"},{"kind":"其他","title":"示意图","evidence_ja":"画像はイメージです。実際とは異なります。","text_zh":"图片是示意，实际物品可能不同。","id":"verified-image-37f0f3b638f1e716aff3","source_url":"https://revuestarlight.com/event/11083/","image_url":"https://revuestarlight.com/wordpress/wp-content/uploads/2026/06/26175938/RS_tokuten_blomide_ari.jpg","image_sha256":"86ffaffb6807eee97f2555e08a96c9b7102c3ced6e701eed17d55b70bf965b7d","checked_on":"2026-10-30"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","本文已公布一般销售入口，但未明确抽选/先着类型，故结构化方式保留未知；公告写10月10日10:00至售完，未在该段写年份，不据此推断当前余票。请查 https://eplus.jp/revuestarlight_1101/ 。"]','published','2026-10-30T14:10:44.737Z','2026-10-30T14:10:44.737Z') on conflict do nothing;
