insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-574a22a1d83b735f','official-574a22a1d83b735f','集え！ゆめみた筋トレ部 ～輝け！上腕二頭筋～','集合！夢限大みゅーたいぷ健身部 ～闪耀吧！肱二头肌～','其他联动','2026年11月21日在东京GARDEN 新木場 FACTORY举办昼夜两场，出演者为仲町あられ与藤都子。站立位置指定票5,900日元（含税），一般发售为先到先得。 入场另付饮料费，终演后由成员赠原创贴纸送客。须着便于运动的服装，站位指定，不得携带大件行李或占位。当前余票须查官方，正文开放日期不保证有票。','{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/08/27161555/785831f3-88ed8c2e-7e6b5011-b95ffaf7.jpg","alt":"集合！夢限大みゅーたいぷ健身部 ～闪耀吧！肱二头肌～","source_url":"https://bang-dream.com/events/yumemita_kinntorebu2026/","checked_on":"2026-10-30"}','[{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/08/27161555/785831f3-88ed8c2e-7e6b5011-b95ffaf7.jpg","alt":"集え！ゆめみた筋トレ部 ～輝け！上腕二頭筋～","source_url":"https://bang-dream.com/events/yumemita_kinntorebu2026/","checked_on":"2026-10-30"},{"url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/09/27133423/c1ed5a66-6638b0b4-9153e038-7fb61d58.jpg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://bang-dream.com/events/yumemita_kinntorebu2026/","checked_on":"2026-10-30"}]','[]','[{"title":"一般发售","text_zh":"2026年10月18日12:00起受理，售罄即止，仅电子票，每人最多2张。","evidence_ja":"※先着順・上限数に達し次第終了\n※スマチケのみの受付となります。\n※お一人様につき2枚までお申込みいただけます。","id":"auto-574a22a1d83b735f-rule-0","kind":"参加","source_url":"https://bang-dream.com/events/yumemita_kinntorebu2026/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"另付饮料费及送客特典","text_zh":"站位指定票5,900日元含税，入场另付饮料费（金额未在正文写明）；终演后成员交付原创贴纸送客。","evidence_ja":"スタンディング（立ち位置指定）：5,900円（税込）\n※入場時に別途ドリンク代が必要となります。\n※終演後、メンバーよりオリジナルステッカーをお渡しするお見送り会を実施します。","id":"auto-574a22a1d83b735f-rule-1","kind":"参加","source_url":"https://bang-dream.com/events/yumemita_kinntorebu2026/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"站位、行李与入场顺序","text_zh":"禁带行李箱及大件，尽量提前寄存，馆内寄存柜数量有限。不得用行李占位或坐地；开场按电子票整理号叫号，迟到者按到达顺序入场。","evidence_ja":"・足元に荷物を置くと転倒事故などに繋がり大変危険です。お荷物は可能な限り、あらかじめコインロッカー等にお預けいただくようお願いいたします。なお、会場のコインロッカーには数に限りがございますので、近隣のコインロッカー等の利用もご検討ください。また、キャリーバックや大きなお荷物の持ち込みは禁止とさせていただきます。\n・手荷物による場所取り行為や座り込みは禁止とさせていただきます。\n・ご入場にあたっては、開場時間になりましたら電子チケットに記載の整理番号順にお呼び出しをさせていただきます。お呼び出し以降にお越しの場合は、会場にお越しいただいた順でのご入場となりますので、あらかじめご了承ください。\nNotice Regarding the Standing Area / 关于站席的注意事项","id":"auto-574a22a1d83b735f-rule-2","kind":"参加","source_url":"https://bang-dream.com/events/yumemita_kinntorebu2026/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"服装","text_zh":"请穿方便活动的服装，并将行李寄存，仅带最少随身物品。","evidence_ja":"※公演の性質上、動きやすい服装でご参加ください。\n※お荷物はコインロッカー等にお預けいただき、手荷物は最小限にしてご来場ください。","id":"auto-574a22a1d83b735f-rule-3","kind":"参加","source_url":"https://bang-dream.com/events/yumemita_kinntorebu2026/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"年龄、有效票与退款","text_zh":"学龄前儿童不得入场，一票一人，仅票面场次及会场有效。除取消或延期外不退票。","evidence_ja":"・未就学児の入場はできません。\n・チケットは券面に記載の公演日、会場でのみ有効となります。\n・1枚のチケットを複数のお客様で使用することはできません（チケット1枚につきお客様1名様のみのご入場となります）。\n・公演中止、延期の場合以外でのチケットの払い戻しはいかなる理由でも行いません。予めご了承ください。","id":"auto-574a22a1d83b735f-rule-4","kind":"参加","source_url":"https://bang-dream.com/events/yumemita_kinntorebu2026/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"身份证明与禁止转售","text_zh":"不得转售或转让，可能检查所有入场者身份；须带1份官方照片证件或照片学生证。无照片学生证须另加本人保险证或其复印件，共2件。仅通过官方电子票功能分配给同行者不在禁止范围。","evidence_ja":"2. チケットの転売・譲渡について\nチケットの転売・譲渡は、いかなる場合も固く禁止しております。\n転売対策のため、入場前に全てのお客様についてご本人様確認を実施させていただく場合がございますので、公的な顔写真付身分証明書1点（免許証・パスポート・在留カード・障害者手帳・顔写真付クレジットカード・顔写真付住民基本台帳カード・マイナンバーカードなど）または顔写真付学生証（生徒手帳・学生手帳）1点を必ずご準備ください。\n顔写真付でない学生証（生徒手帳・学生手帳）をお持ちの方は、顔写真付でない学生証（生徒手帳・学生手帳）1点に加え、ご本人名義の保険証または保険証の写し1点の合計2点をご用意の上、ご来場ください。\n身分証をご提示いただけない場合、入場をお断りする場合がございます。\n※イープラス「スマチケ」など、電子チケットの分配機能を用いた同行者への分配は問題ございません。","id":"auto-574a22a1d83b735f-rule-5","kind":"参加","source_url":"https://bang-dream.com/events/yumemita_kinntorebu2026/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"应援与危险物限制","text_zh":"禁止危险物、非市售或改造手灯、30cm以上及过亮/连结手灯。即使市售也不可挥扔、口衔、单手4根以上、频闪或在头顶持续旋转；不得高举板/扇/玩偶挡人。禁止攀爬、过度跳跃、冲撞、潜水、骑肩、旗帜横幅及发声应援用品。","evidence_ja":"・サイリウム、ペンライトのうち市販されていないもの、改造品、30㎝以上の長さのあるもの、市販されているサイリウム・ペンライト商品のうち光量が著しく大きいもの、連結ペンライト、誘導灯やその他の照明器具を持ち込むこと。なお、入場時の手荷物検査及び会場内にてこれらの物品を係員が発見した場合には、その場でご自身にて破棄していただくか、破棄いただけない場合は入場をお断り、または途中退場していただきます。\n・市販されているサイリウム・ペンライトであっても、振り回す・投げる・口にくわえる・片手に4本以上持つ ・光の点滅を繰り返す・頭上で執拗に回転させるなどして、他のお客様の迷惑になり得る態様で利用すること。\n・持ち手を含まず、面の部分が直径30㎝以上のうちわやメッセージボードを、ご自身の胸の高さ以上の位置で持つこと及び当該うちわやメッセージボードを振り回すなどして、他のお客様の迷惑になり得る態様で利用すること。\n・ぬいぐるみ・おもちゃ等イベント中に使用することを想定されていないグッズ類を、ご自身の胸の高さ以上の位置で持つこと及び当該グッズ類を振り回すなどして、他のお客様の迷惑になり得る態様で利用すること。\n・座席・柵に上ること、座席、柵からジャンプすること。\n・イベントの妨げとなるような、大声を張り上げる・奇声を上げること。\n具体例：通称 家虎、MIX、ワールドカオスと呼ばれる行為等\n・イベントの妨げとなるような大きな音を出すこと、腕を振り回すこと、過度なジャンプ行為。\n具体例：通称 オタ芸と呼ばれる行為等\n・モッシュ・ダイブ・肩車・一定方向に押し寄せること。\n・旗・横断幕・音の出る応援グッズを持ち込むこと。なお、入場時の手荷物検査及び会場内にてこれらの物品を係員が発見した場合には、その場でご自身にて破棄していただくか、破棄いただけない場合は入場をお断り、または途中退場していただきます。\n・正規の手段以外の手段により取得されたチケットでのご入場。","id":"auto-574a22a1d83b735f-rule-6","kind":"参加","source_url":"https://bang-dream.com/events/yumemita_kinntorebu2026/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"安检与违规处理","text_zh":"入场有行李检查，请预留时间。违规可能被核验证件、拒绝入场或退场，不退费用，并可能被长期禁止参加相关活动；严重行为可能报警或采取法律措施。","evidence_ja":"(3) 手荷物検査の強化\n当社が持込を禁止する物品の検査を行うため、イベント入場時の手荷物検査を徹底いたします。\n手荷物検査の実施に伴い、入場時にお時間を要する場合がございますので、時間に余裕をもってイベントへご来場いただけますようお願いいたします。\n(4) 禁止行為を発見した場合の対応\nイベントにおいて禁止行為及びこれに類する行為が発見された場合には、身分証の提示を求めるほか、係員により入場をお断りする、または退場していただくなど厳正に対処いたします。\nなお、イベント中に禁止行為及びこれに類する行為が頻発した場合にはイベントを中断又は中止する場合があります。\n当社は、 禁止行為が認められたお客様については、以後、当社並びに株式会社ブシロード及びその関連会社が関連するすべてのイベント（お渡し会、朗読会、舞台等形式・名称を問いません）への出入りを無期限で禁止させていただきます。万一、入場が確認された場合には、その場で直ちに退場いただきます。禁止行為が認められたお客様が入場不能・退場となった場合でも、イベントチケット代金等の費用の返金には一切応じません。\nまた、 当社は、禁止行為の様態により、禁止行為を行ったお客様に対し、警察への通報、法的措置（民事・刑事を問いません）その他当社が必要と判断する対応を行います。\n（5）免責","id":"auto-574a22a1d83b735f-rule-7","kind":"参加","source_url":"https://bang-dream.com/events/yumemita_kinntorebu2026/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"拍摄与领取物品","text_zh":"原则上禁拍，终演后可在不妨碍他人的范围拍照，上传不得侵犯他人肖像。周边原则上当日在场领取，不接受事前事后寄送，漏领须当日提出；官方可能摄制现场。","evidence_ja":"・グッズ付きチケットをご購入された場合、グッズは原則として会場でのお渡しとなります。いかなる理由でも事前または事後の発送は受け付けておりませんので予めご了承ください。グッズのお受け取り忘れにつきましても、開催当日のご申告のみ対応させていただきます。後日のご連絡にはお応えいたしかねますので、グッズはお忘れなくお受け取りください。その他入場時等の配布物につきましても同様とさせていただきます。\n・会場内での写真撮影は原則として禁止しておりますが、終演後に限り、他のお客様のご迷惑にならない範囲で撮影いただくことが可能です。なお、他のお客様の顔が写っている画像をSNSなどインターネットに掲載された場合は肖像権の侵害となる恐れがありますので、十分にご注意ください。\n・当日は収録等のため、会場内にカメラを設置する場合がございます。後日公開の映像・写真にお客様が映り込むことがございますので、予めご了承ください。","id":"auto-574a22a1d83b735f-rule-8","kind":"参加","source_url":"https://bang-dream.com/events/yumemita_kinntorebu2026/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"酒类与礼物","text_zh":"馆内不售酒，也不得携带酒类；不接收礼物和粉丝来信。","evidence_ja":"・会場内ではアルコールの販売はございません。また、アルコールの持ち込みは禁止とさせていただきます。\n・プレゼント・ファンレターはお控えください。プレゼントボックスも設置は致しません。","id":"auto-574a22a1d83b735f-rule-9","kind":"参加","source_url":"https://bang-dream.com/events/yumemita_kinntorebu2026/","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"kind":"参加","title":"全部为指定站位","evidence_ja":"観覧エリアは全てスタンディング（立ち位置指定）となります。","text_zh":"所有观看区域均为站立席，站立位置指定。","id":"verified-image-fedd0146ccf82b30ca6d","source_url":"https://bang-dream.com/events/yumemita_kinntorebu2026/","image_url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/09/27133423/c1ed5a66-6638b0b4-9153e038-7fb61d58.jpg","image_sha256":"237716c1882765136670138663beb1ed7121871f1cb93987bde3a6d088d5b86c","checked_on":"2026-10-30"},{"kind":"其他","title":"区域图仅为示意","evidence_ja":"画像はイメージです。実際の比率とは異なる場合がございます。","text_zh":"区域图是示意图，实际比例可能不同。","id":"verified-image-3373e975b630691076bb","source_url":"https://bang-dream.com/events/yumemita_kinntorebu2026/","image_url":"https://bang-dream.com/wordpress/wp-content/uploads/2026/09/27133423/c1ed5a66-6638b0b4-9153e038-7fb61d58.jpg","image_sha256":"237716c1882765136670138663beb1ed7121871f1cb93987bde3a6d088d5b86c","checked_on":"2026-10-30"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","仅电子票，每人最多2张，昼场13:30、夜场17:30开演（日本时间）。"]','published','2026-10-30T14:10:44.737Z','2026-10-30T14:10:44.737Z') on conflict do nothing;
