insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-5f0af0901b591f03','official-5f0af0901b591f03','三井ショッピングパーク ららぽーと名古屋みなとアクルス・三井アウトレットパーク 北陸小矢部 × ラブライブ！蓮ノ空女学院スクールアイドルクラブ キャラバンツアー開催決定！','莲之空 Caravan Tour：名古屋港与北陆小矢部','快闪店','2026年11月13日起在两地举办新绘商品、数字集章及赠品企划。名古屋港LaLaport至11月23日；北陆小矢部Outlets仅至11月15日。拥挤时可能限制入场，具体商品、特典门槛和集章条件须查专题；未审核的图片不能替代细则。','{"url":"https://www.lovelive-anime.jp/hasunosora/shared/api/image.php?img_path=/lovelive/jp/news/2026/10/29/1002/S1F0nlXUR5XeZ2DA/3zBLb231kFUuF7lK.jpeg","alt":"莲之空 Caravan Tour：名古屋港与北陆小矢部","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6738","checked_on":"2026-10-30"}','[{"url":"https://www.lovelive-anime.jp/hasunosora/shared/api/image.php?img_path=/lovelive/jp/news/2026/10/29/1002/S1F0nlXUR5XeZ2DA/3zBLb231kFUuF7lK.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6738","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/hasunosora/shared/api/image.php?img_path=/lovelive/jp/news/2026/10/29/1002/VA89ZxKXFXWuHVnw/jNzaHIt31IN8ghPf.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6738","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/hasunosora/shared/api/image.php?img_path=/lovelive/jp/news/2026/10/29/1002/dEDiX0AckyfeBr4S/9ZL2wxnF2wcD4rjr.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6738","checked_on":"2026-10-30"}]','[]','[{"title":"两店期间不同","text_zh":"名古屋港：11月13日至23日；北陆小矢部：11月13日至15日，不能混用结束日期。","evidence_ja":"三井ショッピングパーク ららぽーと名古屋みなとアクルス：2026年11月13日(金) 〜 11月23日(月)\n三井アウトレットパーク 北陸小矢部：2026年11月13日(金) 〜 11月15日(日)","id":"auto-5f0af0901b591f03-rule-0","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6738","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"入场限流","text_zh":"视拥挤情况可能限制入场，最新限流信息由Caravan Tour官方X发布；本公告未具体说明预约、整理券或自由入场。","evidence_ja":"※混雑状況に応じて入場規制が発生する場合がございます。\n※入場規制に関する最新情報は、ラブライブ！シリーズ キャラバンツアー公式Xにて発信いたします。","id":"auto-5f0af0901b591f03-rule-1","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6738","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"企划与后续细则","text_zh":"包括新绘商品、数字集章及赠品企划；详细门槛、数量和参加办法请查 https://lovelive.series-caravan.jp/ ，不得从预告推断。","evidence_ja":"新規描き下ろしグッズの販売をはじめ、デジタルスタンプラリーやノベルティプレゼントキャンペーンなど企画が盛りだくさん！","id":"auto-5f0af0901b591f03-rule-2","kind":"参加","source_url":"https://www.lovelive-anime.jp/hasunosora/news/detail.php?p=01_6738","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","本公告未公布预约细则，不能认定无需预约、现场可入场或有库存；请查看官方活动入口。"]','published','2026-10-30T14:10:44.737Z','2026-10-30T14:10:44.737Z') on conflict do nothing;
