insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-96f2d29dd4fe37bf','official-96f2d29dd4fe37bf','LoveLive! Series 15th Anniversary ラブライブ！フェス','Love Live! 系列15周年 Love Live! Fes','音乐和声优活动','2026年11月14、15日在名古屋Vantelin Dome举行Love Live!系列15周年Fes。新一般先着销售从10月31日12:00起至各演出日前一天23:59（日本时间），仅注释指定席和视线受限席，售完提前结束；本次核实时尚未开放。先着使用手机电子票，无需人脸照片登记，与旧抽选规则区分。','{"url":"https://www.lovelive-anime.jp/special/live/image.php?img_path=/lovelive/jp/live/2026/02/13/1002/MTLGhpBqwB7hnEwW/eHMg6nlsLyB31Vqd.jpeg","alt":"Love Live! 系列15周年 Love Live! Fes","source_url":"https://www.lovelive-anime.jp/special/live/live_detail.php?p=15th_lovelivefest","checked_on":"2026-10-30"}','[{"url":"https://www.lovelive-anime.jp/special/live/image.php?img_path=/lovelive/jp/live/2026/02/13/1002/MTLGhpBqwB7hnEwW/eHMg6nlsLyB31Vqd.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/special/live/live_detail.php?p=15th_lovelivefest","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/special/live/image.php?img_path=/lovelive/jp/live/2026/06/23/1002/ezZMnQ0hwfRo1vly/evegYuG4huwGRm58.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/special/live/live_detail.php?p=15th_lovelivefest","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/special/live/image.php?img_path=/lovelive/jp/live/2026/07/14/1002/9ASTs0ZpHuc6ak2Q/YYmeWvpMGeFDcLIT.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/special/live/live_detail.php?p=15th_lovelivefest","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/special/live/image.php?img_path=/lovelive/jp/live/2026/02/20/1002/zyStMPmKQd0BK1Pk/sxefA7jk5JNDGoW9.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/special/live/live_detail.php?p=15th_lovelivefest","checked_on":"2026-10-30"},{"url":"https://www.lovelive-anime.jp/special/live/image.php