insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-b2f9cf322c26af28','official-b2f9cf322c26af28','ラブライブ！シリーズ×GiGOコラボカフェ秋葉原3号館10周年コラボカフェ開催のお知らせ！','Love Live! × GiGO秋叶原3号馆十周年联动咖啡预告','联动咖啡厅','2026年11月21日至2027年4月11日在GiGOコラボカフェ秋葉原3号館举办Love Live!系列十周年联动咖啡。首弹公开虹咲新绘图；本公告尚未公布各团分期、菜单、预约、价格及特典细则。总期间不能当作虹咲专属期间。','{"url":"https://www.lovelive-anime.jp/nijigasaki/module/image.php?img_path=/lovelive/jp/news/2026/09/28/1002/NjDNMfvTcxgrDLZL/vY6nPzfXjwyOQ59u.jpeg","alt":"Love Live! × GiGO秋叶原3号馆十周年联动咖啡预告","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6659","checked_on":"2026-10-30"}','[{"url":"https://www.lovelive-anime.jp/nijigasaki/module/image.php?img_path=/lovelive/jp/news/2026/09/28/1002/NjDNMfvTcxgrDLZL/vY6nPzfXjwyOQ59u.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6659","checked_on":"2026-10-30"}]','[]','[{"title":"总期间与首弹","text_zh":"11月21日至翌年4月11日是系列联动总期间，首弹为虹咲；虹咲具体结束日与后续分期未写明。","evidence_ja":"GiGOコラボカフェ秋葉原3号館の10周年を記念した、ラブライブ！シリーズとコラボしたカフェを2026年11月21日から2027年4月11日まで開催いたします。\n第1弾の虹ヶ咲メンバーの描き下ろしを大公開！","id":"auto-b2f9cf322c26af28-rule-0","kind":"参加","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6659","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"细则尚待公布","text_zh":"预约方式、菜单价格及特典条件仍待官方后续公告，不推断可直接入场。","evidence_ja":"コラボカフェの詳細は後日発表となります。","id":"auto-b2f9cf322c26af28-rule-1","kind":"参加","source_url":"https://www.lovelive-anime.jp/nijigasaki/detail.php?p=01_6659","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","本公告未公布具体入场预约规则，不能认定无需预约或有余位；请查看所附官方入口。"]','published','2026-10-30T14:10:44.737Z','2026-10-30T14:10:44.737Z') on conflict do nothing;
