insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-e445d0d1659a0d7d','official-e445d0d1659a0d7d','【学マス】「学園アイドルマスター LIVE TOUR -標- ファイナル公演」の開催を記念して、Ｋアリーナ横浜でコラボドリンクの発売が決定！','学园偶像大师「标」最终公演 K-Arena横滨联动饮料','联动咖啡厅','2026年11月6日至8日在K-Arena横滨场外BAYDECK销售，7、8日也在场内指定区域提供。点联动饮料可从A组6款或B组7款中选组随机获卡，特典送完即止。每单最多4杯，BAYDECK店内至少点1份食物及1杯饮料；仅BAYDECK可用现金。场内销售不意味着无票可入场。',null,'[]','[]','[{"title":"随机特典与组选","text_zh":"可选A组6款（咲季、手毬、ことね、燕、麻央、リーリヤ）或B组7款（千奈、清夏、广、星南、美铃、佑芽、莉波），在所选组内随机派发，不能指定角色，送完即止。","evidence_ja":"ノベルティ詳細\nトレーディングカードをランダムでプレゼントいたします。\nA、Bどちらかお好きなパターンからお選びください！\n▼△▼△▼△▼△▼△▼△▼△▼△▼△▼△▼△▼△▼△▼△▼△▼△▼△\nAパターン 全6種からランダム配布\n花海咲季、月村手毬、藤田ことね、雨夜 燕、有村麻央、葛城リーリヤ\nBパターン 全7種からランダム配布\n倉本千奈、紫雲清夏、篠澤 広、十王星南、秦谷美鈴、花海佑芽、姫崎莉波\n▼△▼△▼△▼△▼△▼△▼△▼△▼△▼△▼△▼△▼△▼△▼△▼△▼△\n※購入特典はなくなり次第配布終了となります。あらかじめご了承ください。\n","id":"auto-e445d0d1659a0d7d-rule-0","kind":"参加","source_url":"https://idolmaster-official.jp/news/01_20231","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"11月6日场外营业","text_zh":"BAYDECK店内17:00–23:00，最后点单22:00。","evidence_ja":"🌟 2026年11月6日(金)\n■ Kアリーナ横浜 場外\n・BAYDECK 店内 / 17:00～23:00（ラストオーダー 22:00）","id":"auto-e445d0d1659a0d7d-rule-1","kind":"参加","source_url":"https://idolmaster-official.jp/news/01_20231","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"11月7、8日各点时段","text_zh":"场外BAYDECK外带柜台从物贩开始至开演，店内11:00–22:00、最后点单21:00。场内1/3/5/7层卖店从开场至终演后约1小时，Arena Bar 7从开场至22:00。场内入场资格须另查演出票务，饮料公告不授予入场资格。","evidence_ja":"販売日時・エリア\n🌟 2026年11月6日(金)\n■ Kアリーナ横浜 場外\n・BAYDECK 店内 / 17:00～23:00（ラストオーダー 22:00）\n🌟 2026年11月7日(土)・8日(日)\n■ Ｋアリーナ横浜 場外\n・BAYDECK テイクアウトカウンター / 物販開始時間～開演時間\n・BAYDECK 店内 / 11:00～22:00（ラストオーダー 21:00）\n■ Kアリーナ横浜 場内\n・売店（1・3・5・7Ｆ） / 開場時間 ～ 終演後1時間程度\n・Arena Bar 7 / 開場時間～22:00\n","id":"auto-e445d0d1659a0d7d-rule-2","kind":"参加","source_url":"https://idolmaster-official.jp/news/01_20231","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"杯数、支付与最低点单","text_zh":"每次结账最多4杯；信用卡、电子货币及二维码支付可用，除BAYDECK外不能用现金。BAYDECK店内至少点1份食物及1杯饮料。","evidence_ja":"※1会計あたり4杯までのご購入に限らせていただきます。あらかじめご了承ください。\n※購入特典はなくなり次第配布終了となります。あらかじめご了承ください。\n※コラボドリンクのご利用はクレジットカード各種、電子マネー各種、二次元コード決済各種でのお取り扱いになります。\n現金はご利用いただけません。（BAYDECKのみ現金がご利用いただけます。）\n※BAYDECK店内をご利用のお客様は、1フード・1ドリンク以上のご注文をお願いいたします。","id":"auto-e445d0d1659a0d7d-rule-3","kind":"参加","source_url":"https://idolmaster-official.jp/news/01_20231","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"退换与交易","text_zh":"购买特典除瑕疵品外不可退换；请勿在会场周边或店内进行交换交易。","evidence_ja":"※購入特典の不良品以外の返品・交換は承りません。\n※会場周辺・各店舗内でのトレーディング行為はご遠慮ください。","id":"auto-e445d0d1659a0d7d-rule-4","kind":"参加","source_url":"https://idolmaster-official.jp/news/01_20231","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","此条正式地点为场外BAYDECK店内，至少1食物+1饮料；预约及入店限制本页未写，须向官方确认。场内售卖点仅作补充说明，不能据此无票进入演出会场。"]','published','2026-10-30T14:10:44.737Z','2026-10-30T14:10:44.737Z') on conflict do nothing;
