insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-f17f424f710069c8','official-f17f424f710069c8','いきづらい部！3rd LIVE～いつかみんなで叶いそう～','人生不易部！3rd LIVE ～终有一天，似乎能和大家实现～','音乐和声优活动','2027年3月27、28日东京有明Arena，4月10、11日神户GLION ARENA KOBE。全席指定13,000日元，U-20为6,000日元。官网已将10月31日星期更正为星期六；预购先行抽选为2026年10月31日12:00至11月17日23:59（日本时间），本次核实时尚未开放。','{"url":"https://www.lovelive-anime.jp/lovelive/jp/live/2026/09/20/1002/TWxcotOlGjGB3BKT/3HvEK0mfLbmKCYHM.jpeg","alt":"人生不易部！3rd LIVE ～终有一天，似乎能和大家实现～","source_url":"https://www.lovelive-anime.jp/lovehigh/live/live_detail.php?_id=3rdLIVE","checked_on":"2026-10-30"}','[{"url":"https://www.lovelive-anime.jp/lovelive/jp/live/2026/09/20/1002/TWxcotOlGjGB3BKT/3HvEK0mfLbmKCYHM.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/lovehigh/live/live_detail.php?_id=3rdLIVE","checked_on":"2026-10-30"}]','[]','[{"title":"东京与神户四场","text_zh":"东京3月27日16:00入场17:00开演、28日15:00入场16:00开演；神户4月10日16:00入场17:00开演、11日14:30入场15:30开演。均为日本时间。","evidence_ja":"【日程・会場】\n＜東京公演＞\nDay.1 2027年3月27日（土）16:00開場／17:00開演\nDay.2 2027年3月28日（日）15:00開場／16:00開演\n会場：東京・有明アリーナ\n＜兵庫公演＞\nDay.1 2027年4月10日（土）16:00開場／17:00開演\nDay.2 2027年4月11日（日）14:30開場／15:30開演\n会場：兵庫・GLION ARENA KOBE","id":"auto-f17f424f710069c8-rule-0","kind":"参加","source_url":"https://www.lovelive-anime.jp/lovehigh/live/live_detail.php?_id=3rdLIVE","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"票价及U-20","text_zh":"全席指定13,000日元，U-20为6,000日元；U-20计划随一般销售开放，申请者和同行者在演出当天须均未满20岁，须年龄证明，每人每场2张，不能升席。","evidence_ja":"【チケット料金】\n全席指定席：13,000円（税込）\nU-20割引チケット：6,000円（税込）\nアリーナS席アップグレードチケット（グッズ付き）：＋12,000円（税込/送料別）\nスタンドA席アップグレードチケット（グッズ付き）：＋9,000円（税込/送料別）\n※「アリーナS席アップグレードチケット」はステージに近い前方エリアを予定しております。\n※「スタンドA席アップグレード」はステージに近いステージ正面前方エリアを予定しております。\n※後日、「アップグレードチケット」の抽選受付開始までにアップグレードエリア図面イメージを公開いたします。\n＜「U-20割引チケット」について＞\n本公演は、20歳未満の方にもご参加いただきやすくするため、対象の方に向け「U-20割引チケット」を販売いたします。\n・公演当日時点で20歳未満の方が購入できるチケットとなります。\n・一般発売に合わせ販売予定です。枚数には限りがございますので、あらかじめご了承ください。\n・当日はご入場にあたり、年齢を確認できる身分証明書を確認させていただきます。\n・U-20割引チケットはお一人様1公演につき2枚までお申込みいただけますが、同行者の方も公演当日時点で20歳未満の方に限ります。あらかじめご了承ください。\n・U-20割引チケットはアップグレード対象外となります。","id":"auto-f17f424f710069c8-rule-1","kind":"参加","source_url":"https://www.lovelive-anime.jp/lovehigh/live/live_detail.php?_id=3rdLIVE","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"预购抽选与更正日期","text_zh":"最速先行已于10月25日结束。预购抽选10月31日星期六12:00至11月17日23:59，11月21日13:00公布结果，付款至24日21:00；每人每场4张，可报多场。官网现已修正星期，不再保留已解决的星期冲突。","evidence_ja":"プレオーダー先行（抽選）\n■受付URL： https://eplus.jp/ikizulive_3rd/\n■受付期間：2026年10月31日（土）12:00～11月17日（火）23:59\n■当落発表：2026年11月21日（土）13:00～\n■入金期間：2026年11月21日（土）13:00～11月24日（火）21:00\n※枚数制限： お一人様、 1公演につき4枚までお申込み可能。（複数公演申込可能）","id":"auto-f17f424f710069c8-rule-2","kind":"参加","source_url":"https://www.lovelive-anime.jp/lovehigh/live/live_detail.php?_id=3rdLIVE","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"升席资格和费用","text_zh":"Arena S另加12,000日元、看台A另加9,000日元（均含税、运费另计）。仅已中选并付款者可参加对应轮次；第一轮11月7日12:00至23日23:59仅限最速先行购买者，第二轮11月28日12:00至12月6日23:59也接受预购先行购买者，第二轮仅信用卡支付。","evidence_ja":"アップグレード受付（1次抽選）\n※最速先行抽選でチケットをご購入のお客様のみお申込みいただけます。\n■受付期間：2026年11月7日（土）12:00～11月23日（月・祝）23:59\n■当落発表：2026年11月28日（土）13:00～\n■入金期間：2026年11月28日（土）13:00～12月1日（火）21:00\n※支払い方法：クレジットカード・コンビニ／ATM・ネットバンキング（ペイジー）がお選びいただけます。\nアップグレード受付（2次抽選）\n※最速先行抽選とプレオーダー先行抽選でチケットをご購入のお客様のみお申込みいただけます。\n■受付期間：2026年11月28日（土）12:00～12月6日（日）23:59\n■当落発表：2026年12月12日（土）13:00～\n※支払い方法：クレジットカードのみとなります。","id":"auto-f17f424f710069c8-rule-3","kind":"参加","source_url":"https://www.lovelive-anime.jp/lovehigh/live/live_detail.php?_id=3rdLIVE","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"升席特典配送","text_zh":"特典运费另收，仅配送日本国内地址，不配送海外；避免填写酒店等住宿设施，退回通常不能重新寄送。具体图案尚待公布。","evidence_ja":"※グッズのアイテムやデザイン等詳細は後日発表いたします。\n※グッズは遅くともライブ開催1週間までにご登録いただいた住所へ届くようにイープラスより発送いたします。海外の住所への発送はできません。\n※別途送料がかかります。詳しい送料に関しましては、お申込みページをご確認ください。\n※ご登録住所に不備がないかご確認の上、お申込みいただきますようお願い申し上げます。番地、マンション名、部屋番号等の入力漏れがあるとグッズのお届けができません。\n※発送状況につきましてはイープラスにお問合せください。\n※グッズお届け時にご不在の場合は、配送業者がポストに不在通知を投函いたします。通知に記載の営業所にお客様自身でご連絡の上、保管期限内にお受取りください。\n※長期不在により保管期限を過ぎた場合や住所不明（記載不備含む）の場合、グッズは返送されます。\n※返送されたグッズの再発送は、原則ご対応できかねますので、必ず期限内でのお受取りをお願いいたします。\n※商品の確実な受領と紛失トラブル防止のため、配送先へのホテル・旅館等の宿泊施設のご指定はご遠慮ください。万が一、宿泊施設を配送先に指定された場合、フロントでの受取拒否など不着・紛失が発生する恐れがございます。その際の責任は負いかねますので、あらかじめご了承ください。","id":"auto-f17f424f710069c8-rule-4","kind":"参加","source_url":"https://www.lovelive-anime.jp/lovehigh/live/live_detail.php?_id=3rdLIVE","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"身份与申请","text_zh":"3岁以上收费，需免费eplus会员及手续费；仅受理期内可修改或取消，中选后不能放弃购买。申请者和同行者均须人脸登记，并携带照片证件。","evidence_ja":"●注意事項●\n※3歳以上有料\n※お申込み時にイープラスの会員登録（無料）が必要です。\n※必ず受付画面にて、注意事項をご確認の上、お申込みください。\n※抽選販売分は先着順での受付ではございませんので、受付期間内にお申込みください。当落および座席などは、先着順ではなく、期間内にお申込みいただいた中から抽選で決定いたします。\n※お席に関してのお問合せには、お答えできません。\n※お申込み内容の変更・取消しは受付期間中のみおこなえます。当選後の変更・取消し(購入辞退)は一切お受けできませんのでご注意ください。\n※チケット代金の他に各種手数料が必要となります。\n※アルコール類の持込、及び飲酒してのご入場は固くお断りいたします。\n※開場・開演時間、出演者は諸事情により変更になる場合がございます。それに伴うチケット代・交通費等の払い戻しはいたしません。あらかじめご了承ください。\n※ご来場のお客様におかれましては、公演における注意事項を必ずお読みいただき、遵守くださいますようお願いいたします。ご協力いただけない場合、ご入場いただけない可能性もございますので、あらかじめご了承ください。\n※顔認証入場システムを利用したチケット販売のため、顔写真登録が必要となります。必ず来場者ご本人様がお申込みください。（チケットを複数枚購入される場合、同行者の顔写真登録も必要となります。）\n※顔認証入場システムでご本人と判断できない場合、顔写真付きの公的身分証でご本人確認をさせていただきますので、必ずご持参ください。","id":"auto-f17f424f710069c8-rule-5","kind":"参加","source_url":"https://www.lovelive-anime.jp/lovehigh/live/live_detail.php?_id=3rdLIVE","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"升席须保持原申请与数量","text_zh":"只能由原中选且付款的申请者以相同账号、场次及同行者申请；不得互换申请者与同行者，须将原订单同场门票全部升席，不接受仅部分票。落选仍按普通票入场。","evidence_ja":"※ご当選・ご入金された公演日・会員情報と同一アカウントのお申込ご本人様が抽選対象となります。最速先行抽選受付にて当選された申込者様のアカウントでお申込みください。登録情報を変更されたり、異なるアカウント情報、異なる同行者でお申込みをされた場合、無効となりますのでご注意ください。\n※同一アカウントのお申込みでも、最速先行抽選受付で当選された同行者様が、「アップグレードチケット」の受付で申込者様としてお申込みをされた場合は、無効となりますのでご注意ください。\n例）最速先行抽選受付にてAさんが申込者、Bさんが同行者として当選\n⇒「アップグレードチケット」の受付はBさんが申込者、Aさんが同行者の場合無効\n※最速先行抽選にて2枚購入済みの場合、2枚全てが「アップグレードチケット」の対象となり、一部のみを「アップグレードチケット」としてお申込みは無効となります。\n必ず、最速先行抽選受付にて当選したチケットと同枚数にて、「アップグレードチケット」をお申込みください。\n※チケット代金の他に各種手数料が必要となります。","id":"auto-f17f424f710069c8-rule-6","kind":"参加","source_url":"https://www.lovelive-anime.jp/lovehigh/live/live_detail.php?_id=3rdLIVE","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"U-20身份证明","text_zh":"未满20岁的申请者与同行者均须核验年龄。可持有效官方照片证件或照片学生证（含姓名生日）；无照片证件需至少2种列明证明。户籍/住民票须为3个月内原件，不接受复印件或过期证件。","evidence_ja":"＜U-20割引チケットでのご入場にあたって＞\nU-20割引チケットをご購入のお客様は公演当日の入場時に以下の《顔写真付き身分証明書》によるご本人確認および年齢確認をさせていただきます。\n本券種は公演当日時点で20歳未満の方のみご購入・ご入場いただけるチケット（同行者も同様）となりますので、年齢が確認できない場合はご入場をお断りいたします。\n【1点でご入場いただける身分証明書】\n運転免許証\nパスポート\n顔写真付きマイナンバーカード\n顔写真付き学生証\n在留カード\n特別永住者証明書\nその他公的機関が発行した顔写真付き身分証明書\n※いずれもお名前と生年月日の記載があるものに限ります。\n※上記指定の顔写真付き身分証明書以外のものや、コピー、有効期限の切れたものでのご参加はいかなる場合にもお断りさせていただきます。あらかじめご了承ください。\n《顔写真付身分証明書》をお持ちでない場合は下記身分証の中から２つ以上お持ちください。\n【2点でご入場いただける身分証明書】\n学生証\n社員証\n健康保険資格確認書\n戸籍謄本\n住民票の写し\nその他お名前を確認できる公的機関が発行した身分証明書\n※いずれもお名前と生年月日の記載があるものに限ります。\n※戸籍謄本、住民票は参加される方のお名前が記載あるもので、取得から3ヶ月以内、原本のみ有効です。コピーは無効となります。\n＜会場内でのご観覧にあたって＞","id":"auto-f17f424f710069c8-rule-7","kind":"参加","source_url":"https://www.lovelive-anime.jp/lovehigh/live/live_detail.php?_id=3rdLIVE","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"现场禁止事项","text_zh":"只能在本人座位空间站立，不得冲向舞台或在通道奔跑。禁拍摄录音、饮酒、携酒及等候演员；除补水外客席禁止饮食。电子设备应关机。","evidence_ja":"＜会場内でのご観覧にあたって＞\n・ご自身の座席スペース内に限り、全席スタンディングでの観覧が可能です。\n・場内でステージ等に駆け出す、前方へ押し寄せる、柵を乗り越える、場内や通路を走るなどの行為は大変危険ですので絶対におやめください。\nその他係員が危険な行為と判断した場合は、おやめいただくよう、その場でお声がけをさせていただきます。\nまたチケットに記載の指定のお席以外での鑑賞は、固くお断りいたします。\n・公演の妨げになったり、他のお客様の迷惑になったりするような声援はご遠慮ください。\n・会場内、及び会場付近での録音・撮影等は一切禁止しております。そのような行為が発見された場合、データを消去の上、退場もしくは公演を中止させていただく場合もございます。また、録音・撮影されたと思われるデータの動画サイト・SNS等への無断転載・共有が確認された場合、法的措置も検討いたします。\n・公演中は携帯電話、アラーム等音の出る機器の電源はお切りください。\n・客席内でのご飲食は禁止とさせていただきます。（水分補給は除く）\n・飲酒してのご入場、及び会場内へのアルコール類の持ち込み、場内での飲酒は固くお断りいたします。発見次第、退場処分の場合もございます。\n・会場周辺での出待ち、入待ちは固くお断りいたします。\n＜お荷物について＞","id":"auto-f17f424f710069c8-rule-8","kind":"参加","source_url":"https://www.lovelive-anime.jp/lovehigh/live/live_detail.php?_id=3rdLIVE","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"},{"title":"行李、应援及礼物","text_zh":"不提供行李保管，大件须提前寄存。禁止危险物；扇、板、旗及发声应援品原则禁带，演出官方周边例外但不得挡人。手灯不得改造或长达30cm以上。会场内外禁止交换交易，不接收礼物及信件。","evidence_ja":"＜お荷物について＞\n・カメラ、ビデオカメラ、MD、テープレコーダー、ICレコーダー等の録音録画機器、レーザーポインター、燃料類、大量のライターやマッチ等の可燃性が高いもの、刃物、ハンマー、ドライバー等、凶器として使用される恐れのあるもの、その他スタッフが危険であると判断した物品に関してのお持ち込みは固くお断りいたします。\n・入場時に手荷物検査を実施させていただく場合がございます。\n・受付にてお荷物をお預かりすることはできませんので、キャリーバックのような大きなお荷物は駅内又は近隣のコインロッカー等に予めお預けいただきますよう、ご協力をお願いいたします。\n・お荷物の放置は危険物としての対処や盗難の原因となりますので禁止です。万が一、荷物の盗難や危険物か否かの検査があった場合、ライブ主催者、会場、出演者側では一切責任を負いません。\n＜応援グッズについて＞\n・安全面や、視界・演出の妨げを考慮し、応援グッズのご使用に関して制限をさせていただきます。ご協力のほどお願いいたします。\n・うちわ、メッセージボード、パネル、旗、横断幕、鳴り物（音の出る応援グッズ）など、大小・電飾の有無を問わず、鑑賞の妨げとなりますので、会場への持ち込みやご使用は禁止いたします。ただし、本公演のオフィシャルグッズとして販売されているものは持ち込み可能です。会場内で使用する際は、周りのお客様のご迷惑や鑑賞の妨げにならないよう配慮をお願いいたします。その他係員が危険物と判断した場合は、その場でお声がけをして回収・廃棄等の対応を取らせていただきます。\n・ペンライトやケミカルライト（サイリューム）をご使用の際は、周りのお客様のご迷惑とならないよう、十分にご注意と配慮をお願いいたします。なお、改造ペンライト(著しくまぶしい高輝度タイプへの改造など)や長さが30cm以上の物は、周りのお客様の鑑賞の妨げになりますので、ご使用は禁止といたします。使用を発見した場合、回収・廃棄等の対応を取らせていただきます 。\nその他係員が周りのお客様のご迷惑や鑑賞の妨げとなっていると判断した場合は、その場でお声がけをして、使用を禁止といたします。\nまた、来場者以外の方にも迷惑となりますので、会場周辺、近隣施設での使用も禁止とさせていただきます。\n・ペンライトやケミカルライト（サイリューム）、本公演のオフィシャルグッズ以外の応援グッズのお持ち込みが確認された場合、入り口にてお預かりすることになりますので、あらかじめご了承ください。\n・ご使用後のゴミは各自お持ち帰りいただきますようお願いいたします。\n＜会場物販について＞\n・公演前日及び当日は、会場での直接販売のみとなります。列にお並びの際には係員の指示に従ってください。\n・会場内外並びに近隣施設などでの一切のトレーディング行為を禁止とさせていただきます。\n＜キャストへのプレゼントについて＞","id":"auto-f17f424f710069c8-rule-9","kind":"参加","source_url":"https://www.lovelive-anime.jp/lovehigh/live/live_detail.php?_id=3rdLIVE","image_url":null,"image_sha256":null,"checked_on":"2026-10-30"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","预购先行抽选，每人每场最多4张，可报多场；日本时间10月31日12:00开放。官网星期已更正。需eplus及人脸登记，本轮未注明购CD附券要求。"]','published','2026-10-30T14:10:44.737Z','2026-10-30T14:10:44.737Z') on conflict do nothing;
