insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-50f5f45cf4408056','official-50f5f45cf4408056','ラブライブ！スーパースター!!×相模原市 コラボスタンプラリー実施のお知らせ','Love Live! Superstar!! × 相模原市联动集章活动','其他联动','2026年11月7日至12月27日，在相模原市4个地点举办联动集章活动，各点设置Liella!等身大立牌等展示；可从任一地点开始。集齐4枚章可在市立博物馆或sagamix兑换特制贴纸。JAXA仅明确11月7日14:00以后可自由入场，其余入场条件、休馆日和各点营业时间需查各场馆官网。图片链接已收录，图中文字本轮未能核实。','{"url":"https://www.lovelive-anime.jp/yuigaoka/common/api/image.php?img_path=/lovelive/jp/news/2026/10/29/1002/CUMZ6lejDASCcxF2/rZYHA1grHxjietGr.jpeg","alt":"Love Live! Superstar!! × 相模原市联动集章活动","source_url":"https://www.lovelive-anime.jp/yuigaoka/topics/detail.php?p=01_6751","checked_on":"2026-10-31"}','[{"url":"https://www.lovelive-anime.jp/yuigaoka/common/api/image.php?img_path=/lovelive/jp/news/2026/10/29/1002/CUMZ6lejDASCcxF2/rZYHA1grHxjietGr.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/yuigaoka/topics/detail.php?p=01_6751","checked_on":"2026-10-31"}]','[]','[{"title":"活动期间与开始方式","text_zh":"令和8年即2026年，活动期为11月7日（土）至12月27日（日）。市内4处设置集章台，集章纸预定在这4处摆放，可从任一处开始；设有Liella!成员等身大立牌等。","evidence_ja":"・実施期間\n令和8年11月7日（土）～12月27日（日）まで\n・概要\nスタンプ台は相模原市内、下記設置箇所に記載の4箇所に設置します。\nスタンプラリーシートは下記4か所に配架予定、どこからでもスタートすることが可能です。\nスタンプ設置箇所にはLiella!のメンバーの等身大パネル等を設置します。","id":"auto-50f5f45cf4408056-rule-0","kind":"参加","source_url":"https://www.lovelive-anime.jp/yuigaoka/topics/detail.php?p=01_6751","image_url":null,"image_sha256":null,"checked_on":"2026-10-31"},{"title":"四个集章地点","text_zh":"相模湖观光案内所（绿区与濑1183）；JAXA相模原校园宇宙科学探查交流栋（中央区由野台3-1-1）；相模原市立博物馆（中央区高根3-1-15）；sagamix（南区相模大野3-2-1，bono相模大野购物中心2楼）。","evidence_ja":"・スタンプ設置箇所※\n〇相模湖観光案内所 （相模原市緑区与瀬１１８３）\nhttps://sagamiko.info/archives/52\n〇JAXA相模原キャンパス宇宙科学探査交流棟 （相模原市中央区由野台3-1-1）※\nhttps://www.isas.jaxa.jp/visit/\n〇相模原市立博物館 （相模原市中央区高根３－１－１５）\nhttps://sagamiharacitymuseum.jp/\n〇さがみはらアンテナショップsagamix （相模原市南区相模大野3-2-1ボーノ相模大野ショッピングセンター２階\nhttps://www.e-sagamihara.com/topics/topics-971/","id":"auto-50f5f45cf4408056-rule-1","kind":"参加","source_url":"https://www.lovelive-anime.jp/yuigaoka/topics/detail.php?p=01_6751","image_url":null,"image_sha256":null,"checked_on":"2026-10-31"},{"title":"各点开放日和JAXA入场限制","text_zh":"各处开放日和营业时间以各自官网为准。11月7日因JAXA特别开放活动，仅明确14:00以后可自由入场；当天更早时段的条件以及11月8日以后的入场方式须查官网。不得认定活动全期无需预约。","evidence_ja":"※開館日、営業時間については各スポットの公式サイトをご確認ください。\n※11月7日（土）はJAXA相模原キャンパス特別公開2026を実施中のため、14時以降に自由入場が可能となります。11月8日以降の入場については公式サイトをご確認ください。","id":"auto-50f5f45cf4408056-rule-2","kind":"参加","source_url":"https://www.lovelive-anime.jp/yuigaoka/topics/detail.php?p=01_6751","image_url":null,"image_sha256":null,"checked_on":"2026-10-31"},{"title":"集章特典与兑换地点","text_zh":"集齐全部4枚印章可获特制贴纸；兑换地点为相模原市立博物馆或sagamix。正文未列兑换数量限制、领取时限、库存或费用条件，不能据此保证有货或无其他要求。","evidence_ja":"・クリア限定特典\n４つのスタンプをすべて集めた方に、クリア限定特典として特製ステッカーをプレゼントします。\n〈クリア限定特典配布場所〉 相模原市立博物館／さがみはらアンテナショップsagamix","id":"auto-50f5f45cf4408056-rule-3","kind":"参加","source_url":"https://www.lovelive-anime.jp/yuigaoka/topics/detail.php?p=01_6751","image_url":null,"image_sha256":null,"checked_on":"2026-10-31"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","正文未说明整个集章活动是否需要预约或付费，不能视为无需预约；各点开放日与营业时间须查各自官网。 JAXA仅明确11月7日14:00后可自由入场，11月8日以后的入场条件请查官网。"]','published','2026-10-31T13:58:44.410Z','2026-10-31T13:58:44.410Z') on conflict do nothing;
