insert into public.events (id,slug,title_ja,title_zh,category,summary,image,gallery,benefits,translated_rules,fees,conditions,status,verified_at,updated_at) values ('auto-7fe220332289c14c','official-7fe220332289c14c','あげつち商店街×ラブライブ!サンシャイン!! クリスマスパーティ2026開催のお知らせ','上土商店街 × Love Live! Sunshine!! 圣诞交流会2026','其他联动','2026年12月20日15:00—19:00（预计）在沼津河畔酒店4楼举办粉丝与商店街交流晚宴，每人17,000日元，定员400人。11月1日12:00至11月5日23:59接受抽选报名，可能提前截止；每人、每组仅可报名一次，最多2人。中奖并按期汇款后才算预约完成。官方图片链接已收录，但本轮未取得可验证的图片内容。','{"url":"https://www.lovelive-anime.jp/uranohoshi/topics/image.php?img_path=/lovelive/jp/news/2026/10/31/1002/Ne8XrSqm2Kz26TWL/ppeJjWWeLXzLsIny.jpeg","alt":"上土商店街 × Love Live! Sunshine!! 圣诞交流会2026","source_url":"https://www.lovelive-anime.jp/uranohoshi/detail.php?p=01_6767","checked_on":"2026-10-31"}','[{"url":"https://www.lovelive-anime.jp/uranohoshi/topics/image.php?img_path=/lovelive/jp/news/2026/10/31/1002/Ne8XrSqm2Kz26TWL/ppeJjWWeLXzLsIny.jpeg","alt":"官方公告配图（图中文字请以原图为准）","source_url":"https://www.lovelive-anime.jp/uranohoshi/detail.php?p=01_6767","checked_on":"2026-10-31"}]','[]','[{"title":"日期、会场与地址","text_zh":"2026年12月20日（日）15:00—19:00，时间为预计；会场为沼津河畔酒店4楼大宴会厅 Shangri-La，地址沼津市上土町100番地之1。","evidence_ja":"1、開催日時\n2026年12月20日(日)15:00～19:00(予定)\n2、開催場所\n沼津リバーサイドホテル 4階 大宴会場 (シャングリラ)\n沼津市上土町100番地の1\nhttp://www.numazu-rs-hotel.com","id":"auto-7fe220332289c14c-rule-0","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/detail.php?p=01_6767","image_url":null,"image_sha256":null,"checked_on":"2026-10-31"},{"title":"费用和重复报名限制","text_zh":"每人17,000日元（含税），一次最多申请2人；每人、每组仅限一次。交换代表人与同行者姓名重复申请，或更换邮箱重复报名均无效。","evidence_ja":"3、イベント参加料金\n1名様 17,000円(税込) ※お申込みは2名様まで\n※1人1エントリー、1組1エントリーまでとなります。\n2名申し込みの際名前を入れ替えてのお申込み、アドレスを変えてお申込み等は無効といたします。","id":"auto-7fe220332289c14c-rule-1","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/detail.php?p=01_6767","image_url":null,"image_sha256":null,"checked_on":"2026-10-31"},{"title":"定员","text_zh":"定员400人；申请人数超过定员时，在报名结束后抽选。","evidence_ja":"4、イベント定員\n400名様 ※申込みエントリーが定員を超えた場合はエントリー終了後、抽選とさせていただきます。","id":"auto-7fe220332289c14c-rule-2","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/detail.php?p=01_6767","image_url":null,"image_sha256":null,"checked_on":"2026-10-31"},{"title":"活动内容","text_zh":"与上土商店街及相关人士交流；提供酒店特制西式套餐和软饮料、奖品娱乐活动，以及参加者限定原创特典。特典具体内容未在正文公布。","evidence_ja":"5、イベント内容\n①ラブライブ!サンシャイン!!のファンとあげつち商店街や関係者との交流会\n②沼津リバーサイドホテル特製のコース料理(洋食)とソフトドリンク\n③豪華景品のあたるお楽しみイベント\n④参加者限定のオリジナル特典付き","id":"auto-7fe220332289c14c-rule-3","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/detail.php?p=01_6767","image_url":null,"image_sha256":null,"checked_on":"2026-10-31"},{"title":"报名轮次","text_zh":"通过官方所附表单报名，11月1日（日）12:00至11月5日（四）23:59受理，可能因申请量提前截止；以抽选决定结果。若首轮人数不足，可能追加招募，尚未确定第二轮。该报名段落未重述年份，准确受理时段请以报名入口为准。","evidence_ja":"次ページの申込みフォームによりエントリーをお願いいたします。エントリー受付は11月1日(日)12:00～11月5日(木)23:59の間となります。また一定のエントリー数に達した場合は早めに受付を終了する場合がございますので、その際はご了承くださいませ。 エントリーされた方の中から抽選により当落を決めさせていただきます。(一次受付にて一定のエントリー数に達しなかった場合は二次募集をする場合がございます。)","id":"auto-7fe220332289c14c-rule-4","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/detail.php?p=01_6767","image_url":null,"image_sha256":null,"checked_on":"2026-10-31"},{"title":"结果通知、付款和预约成立","text_zh":"截止后1周内，中奖与落选者都会收到邮件。中奖者取得预约编号后，须在指定期限内通过金融机构汇款，手续费自理；确认到账才算正式预约。逾期未到账自动取消。正文未公布统一付款截止日。","evidence_ja":"抽選に当選された方、落選された方、ともにお申込み締め切り後1週間以内にメールにてご連絡させていただきます。 当選された方には予約番号をご案内いたしますので、指定の期限内に金融機関にてイベント代金のお振込みをお願いいたします。 (お振込み手数料はお客様のご負担にてお願いいたします。) お振込みが確認された時点で正式予約完了となります。 期限内にお振込みが確認されない場合は自動的にキャンセルになりますので、ご注意ください。","id":"auto-7fe220332289c14c-rule-5","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/detail.php?p=01_6767","image_url":null,"image_sha256":null,"checked_on":"2026-10-31"},{"title":"同行者登记","text_zh":"2人参加须填写同行者姓名；代表者与同行者互换姓名分别申请无效。","evidence_ja":"7、お願い\n※お申込みは1人1エントリーまでとなります。より多くの皆様にご参加できるようご協力をよろしくお願い申し上げます。\n※2名参加希望の方はご同行者様のお名前をご記入お願い致します。代表者とご同行者さまそれぞれ名前を入れ替えてのお申込みは無効となります。","id":"auto-7fe220332289c14c-rule-6","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/detail.php?p=01_6767","image_url":null,"image_sha256":null,"checked_on":"2026-10-31"},{"title":"主办与申请入口","text_zh":"由沼津上土商店街与沼津河畔酒店主办；申请入口见原文链接。正文未说明年龄限制、食物过敏安排或取消退款条件，参加前须向主办确认。","evidence_ja":"8、主催\n沼津上土商店街/沼津リバーサイドホテル\nお申込みフォーム\nhttps://biz.entryto.net/detail.php?e_id=53","id":"auto-7fe220332289c14c-rule-7","kind":"参加","source_url":"https://www.lovelive-anime.jp/uranohoshi/detail.php?p=01_6767","image_url":null,"image_sha256":null,"checked_on":"2026-10-31"}]',null,'["中文内容由机器辅助整理，请结合官方原文确认；时间均为日本时间。","官方写明11月1日12:00至11月5日23:59接受报名（日本当地时间），可能提前截止；报名段落未重述年份，准确受理时段请以报名入口为准。通过公告所附 https://biz.entryto.net/detail.php?e_id=53 报名；此处未读取表单，不能保证当前受理或余位。"]','published','2026-10-31T13:58:44.410Z','2026-10-31T13:58:44.410Z') on conflict do nothing;
